{
  "name": "Magalu Order Viewer",
  "description": "A visual interface to query and view Magalu Seller Orders by ID using the Magalu API."
}

// types.ts

export interface Customer {
  uuid?: string;
  name: string;
  document_number?: string;
  email?: string;
  phone_number?: string;
}

export interface Address {
  street: string;
  number: string;
  complement?: string;
  district: string;
  city: string;
  state: string;
  zip_code: string;
  country?: string;
}

export interface OrderItem {
  sku: string;
  name: string;
  quantity: number;
  unit_price: number;
  total_price: number;
}

export interface Order {
  code: string; // The order ID
  channel?: string;
  status: string;
  created_at: string;
  updated_at: string;
  total_amount: number;
  freight_amount?: number;
  discount_amount?: number;
  customer?: Customer;
  shipping_address?: Address;
  items?: OrderItem[];
  // Allow flexible properties since we don't have the full schema
  [key: string]: any; 
}

export interface ApiError {
  message: string;
  status?: number;
}

import { Order, ApiError } from '../types';

/**
 * Fetches an order from the Magalu Seller API.
 * 
 * Note: Browser-based requests to external APIs often encounter CORS (Cross-Origin Resource Sharing) restrictions.
 * If the Magalu API does not permit requests from the browser's origin, this request will fail.
 * In a production environment, this should be proxied through a backend.
 */
export const fetchOrder = async (orderCode: string, token: string): Promise<Order> => {
  if (!orderCode) throw new Error('O código do pedido é obrigatório.');
  if (!token) throw new Error('O token de acesso é obrigatório.');

  const url = `https://api.magalu.com/seller/v1/orders/${orderCode}`;

  try {
    const response = await fetch(url, {
      method: 'GET',
      headers: {
        'Accept': 'application/json',
        'Authorization': `Bearer ${token}`
      }
    });

    if (!response.ok) {
      if (response.status === 401) {
        throw new Error('Não autorizado (401). Verifique se seu Token está correto.');
      }
      if (response.status === 404) {
        throw new Error('Pedido não encontrado (404). Verifique o código.');
      }
      throw new Error(`Erro na API: ${response.status} ${response.statusText}`);
    }

    const data = await response.json();
    return data as Order;
  } catch (error: any) {
    // Handle specific fetch errors (like network/CORS)
    if (error.message === 'Failed to fetch') {
      throw new Error('Falha na conexão. Isso pode ser um bloqueio de CORS. Tente usar uma extensão de navegador para desabilitar CORS para testes ou verifique sua conexão.');
    }
    throw error;
  }
};

import React, { useState, useEffect } from 'react';
import { Search, Key, Package } from 'lucide-react';

interface InputSectionProps {
  onSearch: (orderCode: string, token: string) => void;
  loading: boolean;
}

export const InputSection: React.FC<InputSectionProps> = ({ onSearch, loading }) => {
  const [token, setToken] = useState('');
  const [orderCode, setOrderCode] = useState('');

  // Persist token for convenience
  useEffect(() => {
    const savedToken = localStorage.getItem('magalu_api_token');
    if (savedToken) setToken(savedToken);
  }, []);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (token) {
      localStorage.setItem('magalu_api_token', token);
    }
    onSearch(orderCode, token);
  };

  return (
    <div className="bg-white rounded-xl shadow-md p-6 mb-8 border border-gray-100">
      <form onSubmit={handleSubmit} className="space-y-4">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">

          {/* Token Input */}
          <div className="space-y-2">
            <label htmlFor="token" className="block text-sm font-medium text-gray-700 flex items-center gap-2">
              <Key size={16} /> Token Magalu (Bearer)
            </label>
            <input
              id="token"
              type="password"
              value={token}
              onChange={(e) => setToken(e.target.value)}
              placeholder="Cole seu token aqui..."
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-colors"
              required
            />
          </div>

          {/* Order Code Input */}
          <div className="space-y-2">
            <label htmlFor="orderCode" className="block text-sm font-medium text-gray-700 flex items-center gap-2">
              <Package size={16} /> Código do Pedido
            </label>
            <div className="flex gap-2">
              <input
                id="orderCode"
                type="text"
                value={orderCode}
                onChange={(e) => setOrderCode(e.target.value)}
                placeholder="Ex: LU-123456789"
                className="flex-1 w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-colors"
                required
              />
              <button
                type="submit"
                disabled={loading}
                className={`px-6 py-2 rounded-lg text-white font-medium flex items-center gap-2 transition-all
                  ${loading 
                    ? 'bg-blue-400 cursor-not-allowed' 
                    : 'bg-blue-600 hover:bg-blue-700 shadow-lg hover:shadow-blue-500/30'
                  }`}
              >
                {loading ? (
                  <span>Buscando...</span>
                ) : (
                  <>
                    <Search size={18} /> Buscar
                  </>
                )}
              </button>
            </div>
          </div>

        </div>
        <p className="text-xs text-gray-400 mt-2">
          * O token é salvo localmente no seu navegador para facilitar futuras consultas.
        </p>
      </form>
    </div>
  );
};

import React from 'react';
import { Order } from '../types';
import { User, MapPin, Box, CreditCard, Calendar, ShoppingBag } from 'lucide-react';

interface OrderVisualizerProps {
  order: Order;
}

export const OrderVisualizer: React.FC<OrderVisualizerProps> = ({ order }) => {
  const formatCurrency = (value: number | undefined) => {
    if (value === undefined) return 'R$ 0,00';
    return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(value);
  };

  const formatDate = (dateString: string) => {
    if (!dateString) return '-';
    return new Intl.DateTimeFormat('pt-BR', { dateStyle: 'long', timeStyle: 'short' }).format(new Date(dateString));
  };

  // Determine status color
  const getStatusColor = (status: string) => {
    const s = status.toLowerCase();
    if (s.includes('approved') || s.includes('delivered') || s.includes('faturado')) return 'bg-green-100 text-green-800 border-green-200';
    if (s.includes('cancel')) return 'bg-red-100 text-red-800 border-red-200';
    if (s.includes('pending') || s.includes('new')) return 'bg-yellow-100 text-yellow-800 border-yellow-200';
    return 'bg-gray-100 text-gray-800 border-gray-200';
  };

  return (
    <div className="space-y-6 animate-fade-in">

      {/* Header Info */}
      <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
        <div className="bg-gray-50 px-6 py-4 border-b border-gray-200 flex flex-wrap justify-between items-center gap-4">
          <div>
            <h2 className="text-2xl font-bold text-gray-800 flex items-center gap-2">
              Pedido <span className="font-mono text-blue-600">#{order.code || order.id || 'N/A'}</span>
            </h2>
            <div className="flex items-center gap-2 text-sm text-gray-500 mt-1">
              <Calendar size={14} />
              <span>Criado em: {formatDate(order.created_at)}</span>
            </div>
          </div>
          <span className={`px-4 py-1.5 rounded-full text-sm font-semibold border ${getStatusColor(order.status || 'Desconhecido')}`}>
            {(order.status || 'UNKNOWN').toUpperCase()}
          </span>
        </div>

        <div className="p-6 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">

          {/* Customer Info */}
          <div className="space-y-3">
            <h3 className="text-sm font-semibold text-gray-500 uppercase tracking-wider flex items-center gap-2">
              <User size={16} /> Cliente
            </h3>
            {order.customer ? (
              <div className="text-gray-700">
                <p className="font-medium text-lg">{order.customer.name}</p>
                <p className="text-sm text-gray-500">{order.customer.email}</p>
                <p className="text-sm text-gray-500">{order.customer.phone_number}</p>
                {order.customer.document_number && (
                   <p className="text-xs text-gray-400 mt-1">Doc: {order.customer.document_number}</p>
                )}
              </div>
            ) : (
              <p className="text-gray-400 italic">Dados do cliente indisponíveis</p>
            )}
          </div>

          {/* Shipping Address */}
          <div className="space-y-3">
            <h3 className="text-sm font-semibold text-gray-500 uppercase tracking-wider flex items-center gap-2">
              <MapPin size={16} /> Endereço de Entrega
            </h3>
            {order.shipping_address ? (
              <div className="text-gray-700">
                <p>{order.shipping_address.street}, {order.shipping_address.number}</p>
                <p>{order.shipping_address.complement}</p>
                <p>{order.shipping_address.district}</p>
                <p>{order.shipping_address.city} - {order.shipping_address.state}</p>
                <p className="text-sm text-gray-500 mt-1">{order.shipping_address.zip_code}</p>
              </div>
            ) : (
              <p className="text-gray-400 italic">Endereço indisponível</p>
            )}
          </div>

          {/* Payment Summary */}
          <div className="space-y-3">
            <h3 className="text-sm font-semibold text-gray-500 uppercase tracking-wider flex items-center gap-2">
              <CreditCard size={16} /> Resumo Financeiro
            </h3>
            <div className="bg-gray-50 rounded-lg p-4 space-y-2">
              <div className="flex justify-between text-sm text-gray-600">
                <span>Frete</span>
                <span>{formatCurrency(order.freight_amount || 0)}</span>
              </div>
              <div className="flex justify-between text-sm text-gray-600">
                <span>Desconto</span>
                <span className="text-green-600">-{formatCurrency(order.discount_amount || 0)}</span>
              </div>
              <div className="h-px bg-gray-200 my-2"></div>
              <div className="flex justify-between text-lg font-bold text-gray-900">
                <span>Total</span>
                <span>{formatCurrency(order.total_amount || 0)}</span>
              </div>
            </div>
          </div>

        </div>
      </div>

      {/* Items Table */}
      <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
        <div className="bg-gray-50 px-6 py-4 border-b border-gray-200">
           <h3 className="text-lg font-semibold text-gray-800 flex items-center gap-2">
              <ShoppingBag size={18} /> Itens do Pedido
            </h3>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-gray-50 text-gray-500 text-xs uppercase">
              <tr>
                <th className="px-6 py-3 font-medium">Produto / SKU</th>
                <th className="px-6 py-3 font-medium text-center">Qtd.</th>
                <th className="px-6 py-3 font-medium text-right">Preço Unit.</th>
                <th className="px-6 py-3 font-medium text-right">Total</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-200">
              {order.items && order.items.length > 0 ? (
                order.items.map((item, index) => (
                  <tr key={index} className="hover:bg-gray-50 transition-colors">
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-3">
                        <div className="p-2 bg-blue-50 text-blue-600 rounded-lg">
                            <Box size={20} />
                        </div>
                        <div>
                          <p className="font-medium text-gray-900">{item.name}</p>
                          <p className="text-xs text-gray-500">SKU: {item.sku}</p>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4 text-center text-gray-600">{item.quantity}</td>
                    <td className="px-6 py-4 text-right text-gray-600">{formatCurrency(item.unit_price)}</td>
                    <td className="px-6 py-4 text-right font-medium text-gray-900">{formatCurrency(item.total_price)}</td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan={4} className="px-6 py-8 text-center text-gray-500 italic">
                    Nenhum item listado neste pedido.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

import React from 'react';
import { Code, Copy, Check } from 'lucide-react';

interface RawJsonViewerProps {
  data: any;
}

export const RawJsonViewer: React.FC<RawJsonViewerProps> = ({ data }) => {
  const [copied, setCopied] = React.useState(false);

  const handleCopy = () => {
    navigator.clipboard.writeText(JSON.stringify(data, null, 2));
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="bg-gray-900 rounded-xl overflow-hidden shadow-lg border border-gray-700 mt-8">
      <div className="bg-gray-800 px-4 py-2 flex justify-between items-center border-b border-gray-700">
        <div className="flex items-center gap-2 text-gray-300">
          <Code size={16} />
          <span className="text-sm font-mono font-medium">Resposta JSON Bruta</span>
        </div>
        <button
          onClick={handleCopy}
          className="text-xs flex items-center gap-1.5 px-3 py-1 rounded bg-gray-700 text-gray-300 hover:bg-gray-600 hover:text-white transition-all"
        >
          {copied ? <Check size={12} className="text-green-400" /> : <Copy size={12} />}
          {copied ? 'Copiado!' : 'Copiar'}
        </button>
      </div>
      <div className="p-4 overflow-x-auto">
        <pre className="text-sm font-mono text-green-400 leading-relaxed">
          {JSON.stringify(data, null, 2)}
        </pre>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { InputSection } from './components/InputSection';
import { OrderVisualizer } from './components/OrderVisualizer';
import { RawJsonViewer } from './components/RawJsonViewer';
import { fetchOrder } from './services/magaluService';
import { Order } from './types';
import { ShoppingBag, AlertCircle, Eye, EyeOff } from 'lucide-react';

const App: React.FC = () => {
  const [order, setOrder] = useState<Order | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [showRawJson, setShowRawJson] = useState(false);

  const handleSearch = async (orderCode: string, token: string) => {
    setLoading(true);
    setError(null);
    setOrder(null);
    setShowRawJson(false);

    try {
      const data = await fetchOrder(orderCode, token);
      setOrder(data);
    } catch (err: any) {
      setError(err.message || 'Ocorreu um erro desconhecido ao buscar o pedido.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 pb-12">
      {/* Navbar / Header */}
      <header className="bg-white shadow-sm border-b border-gray-200">
        <div className="max-w-5xl mx-auto px-4 py-4 flex items-center gap-3">
          <div className="bg-blue-600 p-2 rounded-lg text-white shadow-blue-200">
            <ShoppingBag size={24} />
          </div>
          <div>
             <h1 className="text-xl font-bold text-gray-900 tracking-tight">Magalu Order Viewer</h1>
             <p className="text-xs text-gray-500">Visualizador de Pedidos Seller API</p>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="max-w-5xl mx-auto px-4 py-8">

        {/* Search Section */}
        <InputSection onSearch={handleSearch} loading={loading} />

        {/* Error Display */}
        {error && (
          <div className="mb-8 bg-red-50 border-l-4 border-red-500 p-4 rounded-r-lg flex items-start gap-3">
            <AlertCircle className="text-red-500 mt-0.5" size={20} />
            <div>
              <h3 className="text-red-800 font-medium">Erro na consulta</h3>
              <p className="text-red-700 text-sm mt-1">{error}</p>
            </div>
          </div>
        )}

        {/* Results */}
        {order && (
          <div className="animate-fade-in-up">
            <div className="flex justify-end mb-4">
               <button 
                onClick={() => setShowRawJson(!showRawJson)}
                className="text-sm text-gray-500 hover:text-blue-600 flex items-center gap-2 px-3 py-1 rounded-full border border-transparent hover:border-gray-200 transition-all"
               >
                 {showRawJson ? <EyeOff size={14} /> : <Eye size={14} />}
                 {showRawJson ? 'Ocultar JSON Bruto' : 'Ver JSON Bruto'}
               </button>
            </div>

            <OrderVisualizer order={order} />

            {showRawJson && <RawJsonViewer data={order} />}
          </div>
        )}

        {!order && !loading && !error && (
            <div className="text-center py-20 opacity-50">
                <div className="inline-block p-6 bg-gray-100 rounded-full mb-4">
                    <ShoppingBag size={48} className="text-gray-400" />
                </div>
                <h3 className="text-lg font-medium text-gray-600">Nenhum pedido carregado</h3>
                <p className="text-gray-400">Insira seu Token e o Código do Pedido acima para visualizar.</p>
            </div>
        )}

      </main>
    </div>
  );
};

export default App;

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

