import { Order, ApiError } from '../types';

/**
 * Fetches an order from the Magalu Seller API.
 * 
 * Note: Browser-based requests to external APIs often encounter CORS (Cross-Origin Resource Sharing) restrictions.
 * If the Magalu API does not permit requests from the browser's origin, this request will fail.
 * In a production environment, this should be proxied through a backend.
 */
export const fetchOrder = async (orderCode: string, token: string): Promise<Order> => {
  if (!orderCode) throw new Error('O código do pedido é obrigatório.');
  if (!token) throw new Error('O token de acesso é obrigatório.');

  const url = `https://api.magalu.com/seller/v1/orders/${orderCode}`;

  try {
    const response = await fetch(url, {
      method: 'GET',
      headers: {
        'Accept': 'application/json',
        'Authorization': `Bearer ${token}`
      }
    });

    if (!response.ok) {
      if (response.status === 401) {
        throw new Error('Não autorizado (401). Verifique se seu Token está correto.');
      }
      if (response.status === 404) {
        throw new Error('Pedido não encontrado (404). Verifique o código.');
      }
      throw new Error(`Erro na API: ${response.status} ${response.statusText}`);
    }

    const data = await response.json();
    return data as Order;
  } catch (error: any) {
    // Handle specific fetch errors (like network/CORS)
    if (error.message === 'Failed to fetch') {
      throw new Error('Falha na conexão. Isso pode ser um bloqueio de CORS. Tente usar uma extensão de navegador para desabilitar CORS para testes ou verifique sua conexão.');
    }
    throw error;
  }
};

import React, { useState, useEffect } from 'react';
import { Search, Key, Package } from 'lucide-react';

interface InputSectionProps {
  onSearch: (orderCode: string, token: string) => void;
  loading: boolean;
}

export const InputSection: React.FC<InputSectionProps> = ({ onSearch, loading }) => {
  const [token, setToken] = useState('');
  const [orderCode, setOrderCode] = useState('');

  // Persist token for convenience
  useEffect(() => {
    const savedToken = localStorage.getItem('magalu_api_token');
    if (savedToken) setToken(savedToken);
  }, []);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (token) {
      localStorage.setItem('magalu_api_token', token);
    }

    // Clean the order code logic
    // 1. Remove delivery suffix (e.g. LU-12345-1 -> LU-12345)
    // 2. Remove LU- prefix (e.g. LU-12345 -> 12345)
    let cleanedCode = orderCode.trim();

    // First remove suffix like -1, -2 if present
    cleanedCode = cleanedCode.replace(/-\d+$/, '');

    // Then remove LU- prefix (case insensitive)
    cleanedCode = cleanedCode.replace(/^LU-/i, '');

    // Update the UI to show the cleaned code
    if (cleanedCode !== orderCode) {
      setOrderCode(cleanedCode);
    }

    onSearch(cleanedCode, token);
  };

  return (
    <div className="bg-white rounded-xl shadow-md p-6 mb-8 border border-gray-100">
      <form onSubmit={handleSubmit} className="space-y-4">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">

          {/* Token Input */}
          <div className="space-y-2">
            <label htmlFor="token" className="block text-sm font-medium text-gray-700 flex items-center gap-2">
              <Key size={16} /> Token Magalu (Bearer)
            </label>
            <input
              id="token"
              type="password"
              value={token}
              onChange={(e) => setToken(e.target.value)}
              placeholder="Cole seu token aqui..."
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-colors"
              required
            />
          </div>

          {/* Order Code Input */}
          <div className="space-y-2">
            <label htmlFor="orderCode" className="block text-sm font-medium text-gray-700 flex items-center gap-2">
              <Package size={16} /> Código do Pedido
            </label>
            <div className="flex gap-2">
              <input
                id="orderCode"
                type="text"
                value={orderCode}
                onChange={(e) => setOrderCode(e.target.value)}
                placeholder="Ex: 1502870666843360"
                className="flex-1 w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-colors"
                required
              />
              <button
                type="submit"
                disabled={loading}
                className={`px-6 py-2 rounded-lg text-white font-medium flex items-center gap-2 transition-all
                  ${loading 
                    ? 'bg-blue-400 cursor-not-allowed' 
                    : 'bg-blue-600 hover:bg-blue-700 shadow-lg hover:shadow-blue-500/30'
                  }`}
              >
                {loading ? (
                  <span>Buscando...</span>
                ) : (
                  <>
                    <Search size={18} /> Buscar
                  </>
                )}
              </button>
            </div>
            <p className="text-xs text-gray-400">
               Remove automaticamente prefixos "LU-" e sufixos de entrega (ex: -1).
            </p>
          </div>

        </div>
        <p className="text-xs text-gray-400 mt-2">
          * O token é salvo localmente no seu navegador para facilitar futuras consultas.
        </p>
      </form>
    </div>
  );
};

