                          title="Ver Detalhes"
                        >
                          <Eye size={18} />
                        </button>
                      </td>
                    </tr>
                  );
                })
              ) : (
                <tr>
                  <td colSpan={6} className="px-6 py-12 text-center text-gray-400">
                    Nenhum pedido encontrado nesta página.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Tooltip Component - Place outside the loop */}
      <Tooltip 
        id="order-row-tooltip" 
        style={{ 
          backgroundColor: "#1f2937", 
          color: "#fff", 
          padding: "12px", 
          borderRadius: "8px", 
          boxShadow: "0 4px 6px -1px rgba(0, 0, 0, 0.1)",
          zIndex: 50,
          opacity: 1
        }} 
        place="top"
        delayShow={300}
      />
    </div>
  );
};

