import React, { useState, useEffect } from 'react';
import { InputSection } from './components/InputSection';
import { OrderVisualizer } from './components/OrderVisualizer';
import { RawJsonViewer } from './components/RawJsonViewer';
import { OrdersList } from './components/OrdersList';
import { ProductsList } from './components/ProductsList';
import { fetchOrder, fetchOrdersList, fetchPortfolio } from './services/magaluService';
import { Order, OrdersListResponse, PortfolioResponse } from './types';
import { ShoppingBag, AlertCircle, Eye, EyeOff, List, Search, Key, Package } from 'lucide-react';

type Tab = 'search' | 'list' | 'products';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>('search');

  // Search Mode State
  const [order, setOrder] = useState<Order | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // List Mode State
  const [token, setToken] = useState('');
  const [listData, setListData] = useState<OrdersListResponse | null>(null);
  const [listLoading, setListLoading] = useState(false);
  const [listError, setListError] = useState<string | null>(null);
  const [viewingOrderFromList, setViewingOrderFromList] = useState<Order | null>(null);

  // Products Mode State
  const [productsData, setProductsData] = useState<PortfolioResponse | null>(null);
  const [productsLoading, setProductsLoading] = useState(false);
  const [productsError, setProductsError] = useState<string | null>(null);

  const [showRawJson, setShowRawJson] = useState(false);

  // Sync token from localStorage on mount
  useEffect(() => {
    const savedToken = localStorage.getItem('magalu_api_token');
    if (savedToken) setToken(savedToken);
  }, []);

  const handleSearch = async (orderCode: string, inputToken: string) => {
    setLoading(true);
    setError(null);
    setOrder(null);
    setShowRawJson(false);
    // Update global token if changed in input
    if (inputToken !== token) {
      setToken(inputToken);
      localStorage.setItem('magalu_api_token', inputToken);
    }

    try {
      const data = await fetchOrder(orderCode, inputToken);
      setOrder(data);
    } catch (err: any) {
      setError(err.message || 'Ocorreu um erro desconhecido ao buscar o pedido.');
    } finally {
      setLoading(false);
    }
  };

  const handleListFetch = async (offset: number = 0) => {
    if (!token) {
      setListError('Por favor, insira um token válido primeiro.');
      return;
    }

    setListLoading(true);
    setListError(null);
    setViewingOrderFromList(null); // Reset detail view when pagination changes

    try {
      const data = await fetchOrdersList(token, offset);
      setListData(data);
    } catch (err: any) {
      setListError(err.message || 'Erro ao buscar lista de pedidos.');
    } finally {
      setListLoading(false);
    }
  };

  const handleProductsFetch = async (offset: number = 0) => {
    if (!token) {
      setProductsError('Por favor, insira um token válido primeiro.');
      return;
    }

    setProductsLoading(true);
    setProductsError(null);

    try {
      const data = await fetchPortfolio(token, offset);
      setProductsData(data);
    } catch (err: any) {
      setProductsError(err.message || 'Erro ao buscar lista de produtos.');
    } finally {
      setProductsLoading(false);
    }
  };

  const handleTabChange = (tab: Tab) => {
    setActiveTab(tab);
    setError(null);
    setListError(null);
    setProductsError(null);
    setShowRawJson(false);
  };

  return (
    <div className="min-h-screen bg-gray-50 pb-12">
      {/* Navbar / Header */}
      <header className="bg-white shadow-sm border-b border-gray-200 sticky top-0 z-10">
        <div className="max-w-6xl mx-auto px-4 py-4 flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div className="flex items-center gap-3">
            <div className="bg-blue-600 p-2 rounded-lg text-white shadow-blue-200">
              <ShoppingBag size={24} />
            </div>
            <div>
               <h1 className="text-xl font-bold text-gray-900 tracking-tight">Magalu Order Viewer</h1>
               <p className="text-xs text-gray-500">Visualizador de Pedidos & Produtos API</p>
            </div>
          </div>

          {/* Navigation Tabs */}
          <div className="flex p-1 bg-gray-100 rounded-lg overflow-x-auto">
            <button
              onClick={() => handleTabChange('search')}
              className={`px-4 py-2 text-sm font-medium rounded-md flex items-center gap-2 transition-all whitespace-nowrap ${
                activeTab === 'search' 
                  ? 'bg-white text-blue-600 shadow-sm' 
                  : 'text-gray-500 hover:text-gray-700'
              }`}
            >
              <Search size={16} /> Buscar Pedido
            </button>
            <button
              onClick={() => handleTabChange('list')}
              className={`px-4 py-2 text-sm font-medium rounded-md flex items-center gap-2 transition-all whitespace-nowrap ${
                activeTab === 'list' 
                  ? 'bg-white text-blue-600 shadow-sm' 
                  : 'text-gray-500 hover:text-gray-700'
              }`}
            >
              <List size={16} /> Listar Pedidos
            </button>
            <button
              onClick={() => handleTabChange('products')}
              className={`px-4 py-2 text-sm font-medium rounded-md flex items-center gap-2 transition-all whitespace-nowrap ${
                activeTab === 'products' 
                  ? 'bg-white text-blue-600 shadow-sm' 
                  : 'text-gray-500 hover:text-gray-700'
              }`}
            >
              <Package size={16} /> Produtos
            </button>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="max-w-6xl mx-auto px-4 py-8">

        {/* --- TAB: SEARCH --- */}
        {activeTab === 'search' && (
          <div className="animate-fade-in">
            <InputSection onSearch={handleSearch} loading={loading} />

            {error && (
              <div className="mb-8 bg-red-50 border-l-4 border-red-500 p-4 rounded-r-lg flex items-start gap-3">
                <AlertCircle className="text-red-500 mt-0.5" size={20} />
                <div>
                  <h3 className="text-red-800 font-medium">Erro na consulta</h3>
                  <p className="text-red-700 text-sm mt-1">{error}</p>
                </div>
              </div>
            )}

            {order && (
              <div className="animate-fade-in-up">
                <div className="flex justify-end mb-4">
                   <button 
                    onClick={() => setShowRawJson(!showRawJson)}
                    className="text-sm text-gray-500 hover:text-blue-600 flex items-center gap-2 px-3 py-1 rounded-full border border-transparent hover:border-gray-200 transition-all"
                   >
                     {showRawJson ? <EyeOff size={14} /> : <Eye size={14} />}
                     {showRawJson ? 'Ocultar JSON Bruto' : 'Ver JSON Bruto'}
                   </button>
                </div>

                <OrderVisualizer order={order} />

                {showRawJson && <RawJsonViewer data={order} />}
              </div>
            )}

            {!order && !loading && !error && (
                <div className="text-center py-20 opacity-50">
                    <div className="inline-block p-6 bg-gray-100 rounded-full mb-4">
                        <ShoppingBag size={48} className="text-gray-400" />
                    </div>
                    <h3 className="text-lg font-medium text-gray-600">Nenhum pedido carregado</h3>
                    <p className="text-gray-400">Insira seu Token e o Código do Pedido acima para visualizar.</p>
                </div>
            )}
          </div>
        )}

        {/* --- TAB: LIST ORDERS --- */}
        {activeTab === 'list' && (
          <div className="animate-fade-in">

            {/* Simple Token Input for List Mode if not set */}
            <div className="bg-white rounded-xl shadow-md p-6 mb-6 border border-gray-100 flex flex-wrap gap-4 items-end">
               <div className="flex-1 min-w-[300px]">
                  <label className="block text-sm font-medium text-gray-700 mb-1 flex items-center gap-2">
                    <Key size={16} /> Token Magalu (Bearer)
                  </label>
                  <input 
                    type="password" 
                    value={token}
                    onChange={(e) => {
                      setToken(e.target.value);
                      localStorage.setItem('magalu_api_token', e.target.value);
                    }}
                    placeholder="Cole seu token aqui..."
                    className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                  />
               </div>
               <button
                  onClick={() => handleListFetch(0)}
                  disabled={listLoading || !token}
                  className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:bg-blue-300 disabled:cursor-not-allowed font-medium transition-colors h-10"
               >
                 {listLoading ? 'Carregando...' : 'Atualizar Lista'}
               </button>
            </div>

            {listError && (
              <div className="mb-6 bg-red-50 border-l-4 border-red-500 p-4 rounded-r-lg flex items-start gap-3">
                <AlertCircle className="text-red-500 mt-0.5" size={20} />
                <div>
                  <h3 className="text-red-800 font-medium">Erro ao listar</h3>
                  <p className="text-red-700 text-sm mt-1">{listError}</p>
                </div>
              </div>
            )}

            {viewingOrderFromList ? (
               // Detail View from List
               <div className="animate-fade-in-up">
                  <OrderVisualizer 
                    order={viewingOrderFromList} 
                    onBack={() => setViewingOrderFromList(null)} 
                  />
                  <div className="mt-8">
                    <RawJsonViewer data={viewingOrderFromList} />
                  </div>
               </div>
            ) : (
               // List View
               <>
                 {listData ? (
                   <OrdersList 
                      orders={listData.results} 
                      meta={listData.meta} 
                      onPageChange={handleListFetch}
                      onViewOrder={setViewingOrderFromList}
                      loading={listLoading}
                   />
                 ) : (
                   !listLoading && !listError && (
                    <div className="text-center py-20 opacity-50">
                        <div className="inline-block p-6 bg-gray-100 rounded-full mb-4">
                            <List size={48} className="text-gray-400" />
                        </div>
                        <h3 className="text-lg font-medium text-gray-600">Lista vazia</h3>
                        <p className="text-gray-400">Insira seu Token e clique em Atualizar Lista.</p>
                    </div>
                   )
                 )}
               </>
            )}
          </div>
        )}

        {/* --- TAB: PRODUCTS (PORTFOLIO) --- */}
        {activeTab === 'products' && (
          <div className="animate-fade-in">
             <div className="bg-white rounded-xl shadow-md p-6 mb-6 border border-gray-100 flex flex-wrap gap-4 items-end">
               <div className="flex-1 min-w-[300px]">
                  <label className="block text-sm font-medium text-gray-700 mb-1 flex items-center gap-2">
                    <Key size={16} /> Token Magalu (Bearer)
                  </label>
                  <input 
                    type="password" 
                    value={token}
                    onChange={(e) => {
                      setToken(e.target.value);
                      localStorage.setItem('magalu_api_token', e.target.value);
                    }}
                    placeholder="Cole seu token aqui..."
                    className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                  />
               </div>
               <button
                  onClick={() => handleProductsFetch(0)}
                  disabled={productsLoading || !token}
                  className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:bg-blue-300 disabled:cursor-not-allowed font-medium transition-colors h-10"
               >
                 {productsLoading ? 'Carregando...' : 'Buscar Produtos'}
               </button>
            </div>

            {productsError && (
              <div className="mb-6 bg-red-50 border-l-4 border-red-500 p-4 rounded-r-lg flex items-start gap-3">
                <AlertCircle className="text-red-500 mt-0.5" size={20} />
                <div>
                  <h3 className="text-red-800 font-medium">Erro ao buscar produtos</h3>
                  <p className="text-red-700 text-sm mt-1">{productsError}</p>
                </div>
              </div>
            )}

            {productsData ? (
              <>
                <ProductsList 
                  products={productsData.results}
                  meta={productsData.meta}
                  onPageChange={handleProductsFetch}
                  loading={productsLoading}
                />
                <div className="mt-8">
                  {/* Optional: Show raw JSON of the product list if needed */}
                  <div className="flex justify-end mb-2">
                    <button 
                      onClick={() => setShowRawJson(!showRawJson)}
                      className="text-xs text-gray-500 hover:text-blue-600 underline"
                    >
                      {showRawJson ? 'Ocultar JSON' : 'Ver JSON Bruto'}
                    </button>
                  </div>
                  {showRawJson && <RawJsonViewer data={productsData} />}
                </div>
              </>
            ) : (
              !productsLoading && !productsError && (
                <div className="text-center py-20 opacity-50">
                    <div className="inline-block p-6 bg-gray-100 rounded-full mb-4">
                        <Package size={48} className="text-gray-400" />
                    </div>
                    <h3 className="text-lg font-medium text-gray-600">Nenhum produto listado</h3>
                    <p className="text-gray-400">Insira seu Token e clique em Buscar Produtos.</p>
                </div>
              )
            )}
          </div>
        )}

      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Search, Package } from 'lucide-react';

interface InputSectionProps {
  onSearch: (orderCode: string) => void;
  loading: boolean;
}

export const InputSection: React.FC<InputSectionProps> = ({ onSearch, loading }) => {
  const [orderCode, setOrderCode] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    let cleanedCode = orderCode.trim();
    cleanedCode = cleanedCode.replace(/-\d+$/, '');
    cleanedCode = cleanedCode.replace(/^LU-/i, '');

    if (cleanedCode !== orderCode) {
      setOrderCode(cleanedCode);
    }

    onSearch(cleanedCode);
  };

  return (
    <div className="bg-white rounded-xl shadow-md p-6 mb-8 border border-gray-100">
      <form onSubmit={handleSubmit} className="space-y-4">
          <div className="space-y-2">
            <label htmlFor="orderCode" className="block text-sm font-medium text-gray-700 flex items-center gap-2">
              <Package size={16} /> Código do Pedido
            </label>
            <div className="flex gap-2">
              <input
                id="orderCode"
                type="text"
                value={orderCode}
                onChange={(e) => setOrderCode(e.target.value)}
                placeholder="Ex: 1502870666843360"
                className="flex-1 w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-colors"
                required
              />
              <button
                type="submit"
                disabled={loading}
                className={`px-6 py-2 rounded-lg text-white font-medium flex items-center gap-2 transition-all
                  ${loading 
                    ? 'bg-blue-400 cursor-not-allowed' 
                    : 'bg-blue-600 hover:bg-blue-700 shadow-lg hover:shadow-blue-500/30'
                  }`}
              >
                {loading ? (
                  <span>Buscando...</span>
                ) : (
                  <>
                    <Search size={18} /> Buscar
                  </>
                )}
              </button>
            </div>
            <p className="text-xs text-gray-400">
               Remove automaticamente prefixos "LU-" e sufixos de entrega (ex: -1).
            </p>
          </div>
      </form>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { InputSection } from './components/InputSection';
import { OrderVisualizer } from './components/OrderVisualizer';
import { RawJsonViewer } from './components/RawJsonViewer';
import { OrdersList } from './components/OrdersList';
import { ProductsList } from './components/ProductsList';
import { fetchOrder, fetchOrdersList, fetchPortfolio } from './services/magaluService';
import { Order, OrdersListResponse, PortfolioResponse } from './types';
import { ShoppingBag, AlertCircle, Eye, EyeOff, List, Search, Key, Package, RefreshCw } from 'lucide-react';

type Tab = 'search' | 'list' | 'products';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>('search');

  // Global State
  const [token, setToken] = useState('');

  // Search Mode State
  const [order, setOrder] = useState<Order | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // List Mode State
  const [listData, setListData] = useState<OrdersListResponse | null>(null);
  const [listLoading, setListLoading] = useState(false);
  const [listError, setListError] = useState<string | null>(null);
  const [viewingOrderFromList, setViewingOrderFromList] = useState<Order | null>(null);

  // Products Mode State
  const [productsData, setProductsData] = useState<PortfolioResponse | null>(null);
  const [productsLoading, setProductsLoading] = useState(false);
  const [productsError, setProductsError] = useState<string | null>(null);

  const [showRawJson, setShowRawJson] = useState(false);

  // Sync token from localStorage on mount
  useEffect(() => {
    const savedToken = localStorage.getItem('magalu_api_token');
    if (savedToken) setToken(savedToken);
  }, []);

  const handleSearch = async (orderCode: string) => {
    if (!token) {
      setError('Por favor, insira o Token Magalu no topo da página.');
      return;
    }
    setLoading(true);
    setError(null);
    setOrder(null);
    setShowRawJson(false);

    try {
      const data = await fetchOrder(orderCode, token);
      setOrder(data);
    } catch (err: any) {
      setError(err.message || 'Ocorreu um erro desconhecido ao buscar o pedido.');
    } finally {
      setLoading(false);
    }
  };

  const handleListFetch = async (offset: number = 0) => {
    if (!token) {
      setListError('Por favor, insira o Token Magalu no topo da página.');
      return;
    }

    setListLoading(true);
    setListError(null);
    setViewingOrderFromList(null); // Reset detail view when pagination changes

    try {
      const data = await fetchOrdersList(token, offset);
      setListData(data);
    } catch (err: any) {
      setListError(err.message || 'Erro ao buscar lista de pedidos.');
    } finally {
      setListLoading(false);
    }
  };

  const handleProductsFetch = async (offset: number = 0) => {
    if (!token) {
      setProductsError('Por favor, insira o Token Magalu no topo da página.');
      return;
    }

    setProductsLoading(true);
    setProductsError(null);

    try {
      const data = await fetchPortfolio(token, offset);
      setProductsData(data);
    } catch (err: any) {
      setProductsError(err.message || 'Erro ao buscar lista de produtos.');
    } finally {
      setProductsLoading(false);
    }
  };

  const handleTabChange = (tab: Tab) => {
    setActiveTab(tab);
    setError(null);
    setListError(null);
    setProductsError(null);
    setShowRawJson(false);
  };

  return (
    <div className="min-h-screen bg-gray-50 pb-12">
      {/* Navbar / Header */}
      <header className="bg-white shadow-sm border-b border-gray-200 sticky top-0 z-20">
