            {error && (
              <div className="mb-8 bg-red-50 border-l-4 border-red-500 p-4 rounded-r-lg flex items-start gap-3">
                <AlertCircle className="text-red-500 mt-0.5" size={20} />
                <div>
                  <h3 className="text-red-800 font-medium">Erro na consulta</h3>
                  <p className="text-red-700 text-sm mt-1">{error}</p>
                </div>
              </div>
            )}

            {order && (
              <div className="animate-fade-in-up">
                <div className="flex justify-end mb-4">
                   <button 
                    onClick={() => setShowRawJson(!showRawJson)}
                    className="text-sm text-gray-500 hover:text-blue-600 flex items-center gap-2 px-3 py-1 rounded-full border border-transparent hover:border-gray-200 transition-all"
                   >
                     {showRawJson ? <EyeOff size={14} /> : <Eye size={14} />}
                     {showRawJson ? 'Ocultar JSON Bruto' : 'Ver JSON Bruto'}
                   </button>
                </div>

                <OrderVisualizer order={order} />

                {showRawJson && <RawJsonViewer data={order} />}
              </div>
            )}

            {!order && !loading && !error && (
                <div className="text-center py-20 opacity-50">
                    <div className="inline-block p-6 bg-gray-100 rounded-full mb-4">
                        <ShoppingBag size={48} className="text-gray-400" />
                    </div>
                    <h3 className="text-lg font-medium text-gray-600">Nenhum pedido carregado</h3>
                    <p className="text-gray-400">Insira o Código do Pedido abaixo para visualizar.</p>
                </div>
            )}
          </div>
        )}

        {/* --- TAB: LIST ORDERS --- */}
        {activeTab === 'list' && (
          <div className="animate-fade-in">

            {/* Controls */}
            <div className="bg-white rounded-xl shadow-md p-4 mb-6 border border-gray-100 flex justify-end">
               <button
                  onClick={() => handleListFetch(0)}
                  disabled={listLoading || !token}
                  className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:bg-blue-300 disabled:cursor-not-allowed font-medium transition-colors flex items-center gap-2"
               >
                 {listLoading ? <RefreshCw size={18} className="animate-spin" /> : <List size={18} />}
                 {listLoading ? 'Carregando...' : 'Atualizar Lista'}
               </button>
            </div>

            {listError && (
              <div className="mb-6 bg-red-50 border-l-4 border-red-500 p-4 rounded-r-lg flex items-start gap-3">
                <AlertCircle className="text-red-500 mt-0.5" size={20} />
                <div>
                  <h3 className="text-red-800 font-medium">Erro ao listar</h3>
                  <p className="text-red-700 text-sm mt-1">{listError}</p>
                </div>
              </div>
            )}

            {viewingOrderFromList ? (
               // Detail View from List
               <div className="animate-fade-in-up">
                  <OrderVisualizer 
                    order={viewingOrderFromList} 
                    onBack={() => setViewingOrderFromList(null)} 
                  />
                  <div className="mt-8">
                    <RawJsonViewer data={viewingOrderFromList} />
                  </div>
               </div>
            ) : (
               // List View
               <>
                 {listData ? (
                   <OrdersList 
                      orders={listData.results} 
                      meta={listData.meta} 
                      onPageChange={handleListFetch}
                      onViewOrder={setViewingOrderFromList}
                      loading={listLoading}
                   />
                 ) : (
                   !listLoading && !listError && (
                    <div className="text-center py-20 opacity-50">
                        <div className="inline-block p-6 bg-gray-100 rounded-full mb-4">
                            <List size={48} className="text-gray-400" />
                        </div>
                        <h3 className="text-lg font-medium text-gray-600">Lista vazia</h3>
                        <p className="text-gray-400">
                          {!token ? "Insira seu Token no topo da página e clique em Atualizar." : "Clique em Atualizar Lista para carregar."}
                        </p>
                    </div>
                   )
                 )}
               </>
            )}
          </div>
        )}

        {/* --- TAB: PRODUCTS (PORTFOLIO) --- */}
        {activeTab === 'products' && (
          <div className="animate-fade-in">
             {/* Controls */}
             <div className="bg-white rounded-xl shadow-md p-4 mb-6 border border-gray-100 flex justify-end">
               <button
                  onClick={() => handleProductsFetch(0)}
                  disabled={productsLoading || !token}
                  className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:bg-blue-300 disabled:cursor-not-allowed font-medium transition-colors flex items-center gap-2"
               >
                 {productsLoading ? <RefreshCw size={18} className="animate-spin" /> : <Package size={18} />}
                 {productsLoading ? 'Carregando...' : 'Buscar Produtos'}
               </button>
            </div>

            {productsError && (
              <div className="mb-6 bg-red-50 border-l-4 border-red-500 p-4 rounded-r-lg flex items-start gap-3">
                <AlertCircle className="text-red-500 mt-0.5" size={20} />
                <div>
                  <h3 className="text-red-800 font-medium">Erro ao buscar produtos</h3>
                  <p className="text-red-700 text-sm mt-1">{productsError}</p>
                </div>
              </div>
            )}

            {productsData ? (
              <>
                <ProductsList 
                  products={productsData.results}
                  meta={productsData.meta}
                  onPageChange={handleProductsFetch}
                  loading={productsLoading}
                />
                <div className="mt-8">
                  <div className="flex justify-end mb-2">
                    <button 
                      onClick={() => setShowRawJson(!showRawJson)}
                      className="text-xs text-gray-500 hover:text-blue-600 underline"
                    >
                      {showRawJson ? 'Ocultar JSON' : 'Ver JSON Bruto'}
                    </button>
                  </div>
                  {showRawJson && <RawJsonViewer data={productsData} />}
                </div>
              </>
            ) : (
              !productsLoading && !productsError && (
                <div className="text-center py-20 opacity-50">
                    <div className="inline-block p-6 bg-gray-100 rounded-full mb-4">
                        <Package size={48} className="text-gray-400" />
                    </div>
                    <h3 className="text-lg font-medium text-gray-600">Nenhum produto listado</h3>
                    <p className="text-gray-400">
                      {!token ? "Insira seu Token no topo da página e clique em Buscar Produtos." : "Clique em Buscar Produtos para carregar."}
                    </p>
                </div>
              )
            )}
          </div>
        )}

      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Product, PaginationMeta } from '../types';
import { formatDate, getStatusConfig } from '../utils';
import { 
  ChevronLeft, ChevronRight, ChevronsLeft, ChevronsRight, 
  Search, Package, ImageOff, ExternalLink 
} from 'lucide-react';
import { Tooltip } from 'react-tooltip';

interface ProductsListProps {
  products: Product[];
  meta: PaginationMeta;
  onPageChange: (offset: number) => void;
  loading: boolean;
}

export const ProductsList: React.FC<ProductsListProps> = ({ 
  products, 
  meta, 
  onPageChange, 
  loading
}) => {
  const [filter, setFilter] = useState('');

  // Local filtering
  const filteredProducts = products.filter(p => 
    p.sku.toLowerCase().includes(filter.toLowerCase()) || 
    p.title.toLowerCase().includes(filter.toLowerCase())
  );

  // Pagination Logic
  const totalPages = Math.ceil(meta.page.count / meta.page.limit);
  const currentPage = Math.floor(meta.page.offset / meta.page.limit) + 1;

  const goToPage = (page: number) => {
    const newOffset = (page - 1) * meta.page.limit;
    onPageChange(newOffset);
  };

  const handlePrev = () => {
    if (meta.page.offset > 0) {
      const newOffset = Math.max(0, meta.page.offset - meta.page.limit);
      onPageChange(newOffset);
    }
  };

  const handleNext = () => {
    const nextOffset = meta.page.offset + meta.page.limit;
    if (nextOffset < meta.page.count) {
      onPageChange(nextOffset);
    }
  };

  const getPageNumbers = () => {
    const pages: (number | string)[] = [];

    if (totalPages <= 7) {
      for (let i = 1; i <= totalPages; i++) pages.push(i);
    } else {
      if (currentPage <= 4) {
        pages.push(1, 2, 3, 4, 5, '...', totalPages);
      } else if (currentPage >= totalPages - 3) {
        pages.push(1, '...', totalPages - 4, totalPages - 3, totalPages - 2, totalPages - 1, totalPages);
      } else {
        pages.push(1, '...', currentPage - 1, currentPage, currentPage + 1, '...', totalPages);
      }
    }
    return pages;
  };

  return (
    <div className="space-y-4 animate-fade-in">
      {/* Top Controls: Search & Summary */}
      <div className="flex flex-col sm:flex-row justify-between gap-4 items-center">
        <div className="relative w-full sm:w-auto">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
          <input 
            type="text" 
            placeholder="Filtrar por SKU ou Título nesta página..."
            value={filter}
            onChange={(e) => setFilter(e.target.value)}
            className="pl-10 pr-4 py-2 border border-gray-300 rounded-lg w-full sm:w-80 focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
          />
        </div>

        <div className="text-sm text-gray-600 bg-white px-4 py-2 rounded-lg border border-gray-200 shadow-sm">
          Mostrando <b>{meta.page.offset + 1}</b> - <b>{Math.min(meta.page.offset + meta.page.limit, meta.page.count)}</b> de <b>{meta.page.count}</b> resultados
        </div>
      </div>

      {/* Table */}
      <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-gray-50 border-b border-gray-200 text-gray-500 text-xs uppercase tracking-wider font-semibold">
              <tr>
                <th className="px-6 py-3 w-20">Img</th>
                <th className="px-6 py-3">Produto</th>
                <th className="px-6 py-3">Marca</th>
                <th className="px-6 py-3 text-center">Status</th>
                <th className="px-6 py-3 text-right">Data Criação</th>
                <th className="px-6 py-3 text-center">Link</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {loading ? (
                [...Array(5)].map((_, i) => (
                  <tr key={i} className="animate-pulse">
                    <td className="px-6 py-4"><div className="h-10 w-10 bg-gray-200 rounded"></div></td>
                    <td className="px-6 py-4">
                      <div className="h-4 bg-gray-200 rounded w-3/4 mb-2"></div>
                      <div className="h-3 bg-gray-200 rounded w-1/4"></div>
                    </td>
                    <td className="px-6 py-4"><div className="h-4 bg-gray-200 rounded w-20"></div></td>
                    <td className="px-6 py-4"><div className="h-6 bg-gray-200 rounded w-24 mx-auto"></div></td>
                    <td className="px-6 py-4"><div className="h-4 bg-gray-200 rounded w-24 ml-auto"></div></td>
                    <td className="px-6 py-4"><div className="h-4 w-4 bg-gray-200 rounded mx-auto"></div></td>
                  </tr>
                ))
              ) : filteredProducts.length > 0 ? (
                filteredProducts.map((product) => {
                  const status = getStatusConfig(product.status);
                  const mainImage = product.images?.[0]?.reference;
                  const marketplaceUrl = product.url_marketplace?.find(u => u.channel === 'magazineluiza')?.url;

                  return (
                    <tr 
                      key={product.sku} 
                      className="hover:bg-gray-50 transition-colors group"
                      data-tooltip-id="product-tooltip"
                      data-tooltip-html={`
                        <div class="max-w-xs">
                          <p class="font-bold border-b border-gray-500 pb-1 mb-1">${product.title}</p>
                          <p class="text-xs">SKU: ${product.sku}</p>
                          <p class="text-xs">Condição: ${product.condition}</p>
                        </div>
                      `}
                    >
                      <td className="px-6 py-3">
                        <div className="w-12 h-12 bg-white border border-gray-200 rounded-md flex items-center justify-center overflow-hidden">
                          {mainImage ? (
                            <img src={mainImage} alt={product.sku} className="w-full h-full object-contain" />
                          ) : (
                            <ImageOff size={20} className="text-gray-300" />
                          )}
                        </div>
                      </td>
                      <td className="px-6 py-3">
                        <p className="text-sm font-medium text-gray-900 line-clamp-2">{product.title}</p>
                        <p className="text-xs text-gray-500 font-mono mt-0.5">SKU: {product.sku}</p>
                      </td>
                      <td className="px-6 py-3 text-sm text-gray-600">
                        {product.brand}
                      </td>
                      <td className="px-6 py-3 text-center">
                        <span className={`inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-xs font-medium border ${status.style}`}>
                          {status.icon}
                          {status.label}
                        </span>
                      </td>
                      <td className="px-6 py-3 text-right text-sm text-gray-600 font-mono">
                        {formatDate(product.created_at)}
                      </td>
                      <td className="px-6 py-3 text-center">
                        {marketplaceUrl ? (
                          <a 
                            href={marketplaceUrl} 
                            target="_blank" 
                            rel="noopener noreferrer"
                            className="p-2 text-blue-600 hover:bg-blue-50 rounded-lg transition-colors inline-block"
                            title="Ver no Magalu"
                            onClick={(e) => e.stopPropagation()}
                          >
                            <ExternalLink size={18} />
                          </a>
                        ) : (
                          <span className="text-gray-300">-</span>
                        )}
                      </td>
                    </tr>
                  );
                })
              ) : (
                <tr>
                  <td colSpan={6} className="px-6 py-12 text-center text-gray-400">
                    <div className="flex flex-col items-center gap-2">
                      <Package size={32} className="opacity-50" />
                      <p>Nenhum produto encontrado.</p>
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>

        {/* Bottom Pagination Controls */}
        <div className="bg-gray-50 px-6 py-4 border-t border-gray-200 flex items-center justify-center sm:justify-between flex-wrap gap-4">
           <div className="hidden sm:block text-sm text-gray-500">
              Página {currentPage} de {totalPages}
           </div>

           <div className="flex items-center gap-1">
              <button 
                onClick={() => goToPage(1)}
                disabled={currentPage === 1 || loading}
                className="p-2 rounded-md hover:bg-gray-200 text-gray-600 disabled:opacity-30 disabled:cursor-not-allowed"
                title="Primeira Página"
              >
                <ChevronsLeft size={18} />
              </button>
              <button 
                onClick={handlePrev}
                disabled={currentPage === 1 || loading}
                className="p-2 rounded-md hover:bg-gray-200 text-gray-600 disabled:opacity-30 disabled:cursor-not-allowed"
                title="Página Anterior"
              >
                <ChevronLeft size={18} />
              </button>

              <div className="flex items-center gap-1 mx-2">
                {getPageNumbers().map((page, idx) => (
                  <button
                    key={idx}
                    onClick={() => typeof page === 'number' ? goToPage(page) : null}
                    disabled={page === '...' || loading}
                    className={`
                      w-8 h-8 flex items-center justify-center rounded-md text-sm font-medium transition-colors
                      ${page === currentPage 
                        ? 'bg-blue-600 text-white shadow-sm' 
                        : page === '...' 
                          ? 'text-gray-400 cursor-default' 
                          : 'bg-white text-gray-700 border border-gray-300 hover:bg-gray-50'
                      }
                    `}
                  >
                    {page}
                  </button>
                ))}
              </div>

              <button 
                onClick={handleNext}
                disabled={currentPage === totalPages || loading}
                className="p-2 rounded-md hover:bg-gray-200 text-gray-600 disabled:opacity-30 disabled:cursor-not-allowed"
                title="Próxima Página"
              >
                <ChevronRight size={18} />
              </button>
              <button 
                onClick={() => goToPage(totalPages)}
                disabled={currentPage === totalPages || loading}
                className="p-2 rounded-md hover:bg-gray-200 text-gray-600 disabled:opacity-30 disabled:cursor-not-allowed"
                title="Última Página"
              >
                <ChevronsRight size={18} />
              </button>
           </div>
        </div>
      </div>

      <Tooltip 
        id="product-tooltip" 
        style={{ 
          backgroundColor: "#1f2937", 
          color: "#fff", 
          padding: "12px", 
          borderRadius: "8px", 
          zIndex: 50,
          opacity: 1
        }} 
        place="top"
        delayShow={500}
      />
    </div>
  );
};

import React, { useState } from 'react';
import { Product, PaginationMeta } from '../types';
import { formatDate, getStatusConfig } from '../utils';
import { 
  ChevronLeft, ChevronRight, Search, Package, ImageOff, ExternalLink 
} from 'lucide-react';
import { Tooltip } from 'react-tooltip';

interface ProductsListProps {
  products: Product[];
  meta: PaginationMeta;
  onPageChange: (offset: number) => void;
  loading: boolean;
  limit: number;
  onLimitChange: (limit: number) => void;
}

export const ProductsList: React.FC<ProductsListProps> = ({ 
  products, 
  meta, 
  onPageChange, 
  loading,
  limit,
  onLimitChange
}) => {
  const [filter, setFilter] = useState('');

  // Local filtering
  const filteredProducts = products.filter(p => 
    p.sku.toLowerCase().includes(filter.toLowerCase()) || 
    p.title.toLowerCase().includes(filter.toLowerCase())
  );

  // Pagination Logic
  // Using links from meta to determine navigation availability
  // meta.page.offset is the starting index (0, 20, 40...)
  const currentPage = Math.floor(meta.page.offset / limit) + 1;
  const hasNextPage = !!meta.links.next;
  const hasPrevPage = !!meta.links.previous || meta.page.offset > 0;

  const handlePrev = () => {
    if (hasPrevPage) {
      const newOffset = Math.max(0, meta.page.offset - limit);
      onPageChange(newOffset);
    }
  };

  const handleNext = () => {
    if (hasNextPage) {
      const nextOffset = meta.page.offset + limit;
      onPageChange(nextOffset);
    }
  };

  const handleLimitChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const newLimit = parseInt(e.target.value, 10);
    onLimitChange(newLimit);
  };

  return (
    <div className="space-y-4 animate-fade-in">
      {/* Top Controls: Search & Summary */}
      <div className="flex flex-col sm:flex-row justify-between gap-4 items-center">
        <div className="relative w-full sm:w-auto">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
          <input 
            type="text" 
            placeholder="Filtrar por SKU ou Título nesta página..."
            value={filter}
            onChange={(e) => setFilter(e.target.value)}
            className="pl-10 pr-4 py-2 border border-gray-300 rounded-lg w-full sm:w-80 focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
          />
        </div>

        <div className="flex flex-wrap items-center gap-3 justify-end">
          <div className="flex items-center gap-2 text-sm text-gray-600 bg-white px-2 py-1 rounded border border-gray-200">
             <span className="hidden sm:inline">Itens:</span>
             <select 
              value={limit} 
              onChange={handleLimitChange}
              disabled={loading}
              className="border-none bg-transparent text-sm font-medium focus:ring-0 cursor-pointer"
             >
               <option value={10}>10</option>
               <option value={20}>20</option>
               <option value={50}>50</option>
               <option value={100}>100</option>
             </select>
          </div>

          <div className="text-sm text-gray-600 bg-white px-4 py-2 rounded-lg border border-gray-200 shadow-sm whitespace-nowrap">
            Exibindo <b>{meta.page.offset + 1}</b> - <b>{meta.page.offset + products.length}</b>
          </div>
        </div>
      </div>

      {/* Table */}
      <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-gray-50 border-b border-gray-200 text-gray-500 text-xs uppercase tracking-wider font-semibold">
              <tr>
                <th className="px-6 py-3 w-20">Img</th>
                <th className="px-6 py-3">Produto</th>
                <th className="px-6 py-3">Marca</th>
                <th className="px-6 py-3 text-center">Status</th>
                <th className="px-6 py-3 text-right">Data Criação</th>
                <th className="px-6 py-3 text-center">Link</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {loading ? (
                [...Array(5)].map((_, i) => (
                  <tr key={i} className="animate-pulse">
                    <td className="px-6 py-4"><div className="h-10 w-10 bg-gray-200 rounded"></div></td>
                    <td className="px-6 py-4">
                      <div className="h-4 bg-gray-200 rounded w-3/4 mb-2"></div>
                      <div className="h-3 bg-gray-200 rounded w-1/4"></div>
                    </td>
                    <td className="px-6 py-4"><div className="h-4 bg-gray-200 rounded w-20"></div></td>
                    <td className="px-6 py-4"><div className="h-6 bg-gray-200 rounded w-24 mx-auto"></div></td>
                    <td className="px-6 py-4"><div className="h-4 bg-gray-200 rounded w-24 ml-auto"></div></td>
                    <td className="px-6 py-4"><div className="h-4 w-4 bg-gray-200 rounded mx-auto"></div></td>
                  </tr>
                ))
              ) : filteredProducts.length > 0 ? (
                filteredProducts.map((product) => {
                  const status = getStatusConfig(product.status);
                  const mainImage = product.images?.[0]?.reference;
                  const marketplaceUrl = product.url_marketplace?.find(u => u.channel === 'magazineluiza')?.url;

                  return (
                    <tr 
                      key={product.sku} 
                      className="hover:bg-gray-50 transition-colors group"
                      data-tooltip-id="product-tooltip"
                      data-tooltip-html={`
                        <div class="max-w-xs">
                          <p class="font-bold border-b border-gray-500 pb-1 mb-1">${product.title}</p>
                          <p class="text-xs">SKU: ${product.sku}</p>
                          <p class="text-xs">Condição: ${product.condition}</p>
                        </div>
                      `}
                    >
                      <td className="px-6 py-3">
                        <div className="w-12 h-12 bg-white border border-gray-200 rounded-md flex items-center justify-center overflow-hidden">
                          {mainImage ? (
                            <img src={mainImage} alt={product.sku} className="w-full h-full object-contain" />
                          ) : (
                            <ImageOff size={20} className="text-gray-300" />
                          )}
                        </div>
                      </td>
                      <td className="px-6 py-3">
                        <p className="text-sm font-medium text-gray-900 line-clamp-2">{product.title}</p>
                        <p className="text-xs text-gray-500 font-mono mt-0.5">SKU: {product.sku}</p>
                      </td>
                      <td className="px-6 py-3 text-sm text-gray-600">
                        {product.brand}
                      </td>
                      <td className="px-6 py-3 text-center">
                        <span className={`inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-xs font-medium border ${status.style}`}>
                          {status.icon}
                          {status.label}
                        </span>
                      </td>
                      <td className="px-6 py-3 text-right text-sm text-gray-600 font-mono">
                        {formatDate(product.created_at)}
                      </td>
                      <td className="px-6 py-3 text-center">
                        {marketplaceUrl ? (
                          <a 
                            href={marketplaceUrl} 
                            target="_blank" 
                            rel="noopener noreferrer"
                            className="p-2 text-blue-600 hover:bg-blue-50 rounded-lg transition-colors inline-block"
                            title="Ver no Magalu"
                            onClick={(e) => e.stopPropagation()}
                          >
                            <ExternalLink size={18} />
                          </a>
                        ) : (
                          <span className="text-gray-300">-</span>
                        )}
                      </td>
                    </tr>
                  );
                })
              ) : (
                <tr>
                  <td colSpan={6} className="px-6 py-12 text-center text-gray-400">
                    <div className="flex flex-col items-center gap-2">
                      <Package size={32} className="opacity-50" />
