                    rel="noopener noreferrer"
                    className="inline-flex items-center gap-2 text-sm font-medium text-blue-600 hover:text-blue-800 hover:underline"
                  >
                    <ExternalLink size={16} /> Ver no Magazine Luiza
                  </a>
                </div>
             )}
