              <Box size={18} className="text-blue-500" /> Ficha Técnica
            </h3>

            <div className="space-y-3 max-h-60 overflow-y-auto pr-2 custom-scrollbar">
               {product.identifiers && product.identifiers.length > 0 && (
                 <div className="mb-4">
