import { Order, OrdersListResponse, PortfolioResponse, Product, PriceResponse, StockResponse, ApiError } from '../types';

/**
 * Fetches a single order from the Magalu Seller API.
 */
export const fetchOrder = async (orderCode: string, token: string): Promise<Order> => {
  if (!orderCode) throw new Error('O código do pedido é obrigatório.');
  if (!token) throw new Error('O token de acesso é obrigatório.');

  const url = `https://api.magalu.com/seller/v1/orders/${orderCode}`;

  try {
    const response = await fetch(url, {
      method: 'GET',
      headers: {
        'Accept': 'application/json',
        'Authorization': `Bearer ${token}`
      }
    });

    if (!response.ok) {
      if (response.status === 401) {
        throw new Error('Não autorizado (401). Verifique se seu Token está correto.');
      }
      if (response.status === 404) {
        throw new Error('Pedido não encontrado (404). Verifique o código.');
      }
      throw new Error(`Erro na API: ${response.status} ${response.statusText}`);
    }

    const data = await response.json();
    return data as Order;
  } catch (error: any) {
    if (error.message === 'Failed to fetch') {
      throw new Error('Falha na conexão. Isso pode ser um bloqueio de CORS. Tente usar uma extensão de navegador para desabilitar CORS para testes ou verifique sua conexão.');
    }
    throw error;
  }
};

/**
 * Fetches a list of orders from the Magalu Seller API with pagination.
 */
export const fetchOrdersList = async (token: string, offset: number = 0, limit: number = 20): Promise<OrdersListResponse> => {
  if (!token) throw new Error('O token de acesso é obrigatório.');

  // Construct URL with query parameters
  const url = new URL('https://api.magalu.com/seller/v1/orders');
  url.searchParams.append('_offset', offset.toString());
  url.searchParams.append('limit', limit.toString());

  try {
    const response = await fetch(url.toString(), {
      method: 'GET',
      headers: {
        'Accept': 'application/json',
        'Authorization': `Bearer ${token}`
      }
    });

    if (!response.ok) {
      if (response.status === 401) {
        throw new Error('Não autorizado (401). Verifique se seu Token está correto.');
      }
      throw new Error(`Erro na API: ${response.status} ${response.statusText}`);
    }

    const data = await response.json();
    return data as OrdersListResponse;
  } catch (error: any) {
    if (error.message === 'Failed to fetch') {
      throw new Error('Falha na conexão. Isso pode ser um bloqueio de CORS. Tente usar uma extensão de navegador para desabilitar CORS para testes ou verifique sua conexão.');
    }
    throw error;
  }
};

/**
 * Fetches a list of products (Portfolio SKUs) from the Magalu Seller API.
 */
export const fetchPortfolio = async (token: string, offset: number = 0, limit: number = 20): Promise<PortfolioResponse> => {
  if (!token) throw new Error('O token de acesso é obrigatório.');

  const url = new URL('https://api.magalu.com/seller/v1/portfolios/skus');
  url.searchParams.append('_offset', offset.toString());
  url.searchParams.append('_limit', limit.toString()); // Note: _limit vs limit in orders API might differ, sticking to user docs which says _limit for portfolios

  try {
    const response = await fetch(url.toString(), {
      method: 'GET',
      headers: {
        'Accept': 'application/json',
        'Authorization': `Bearer ${token}`
      }
    });

    if (!response.ok) {
      if (response.status === 401) {
        throw new Error('Não autorizado (401). Verifique se seu Token está correto.');
      }
      throw new Error(`Erro na API: ${response.status} ${response.statusText}`);
    }

    const data = await response.json();
    return data as PortfolioResponse;
  } catch (error: any) {
    if (error.message === 'Failed to fetch') {
      throw new Error('Falha na conexão. Isso pode ser um bloqueio de CORS.');
    }
    throw error;
  }
};

/**
 * Fetches a single product (SKU) from the Magalu Seller API.
 */
export const fetchProduct = async (sku: string, token: string): Promise<Product> => {
  if (!sku) throw new Error('O SKU é obrigatório.');
  if (!token) throw new Error('O token de acesso é obrigatório.');

  // URL encode the SKU as it might contain special characters
  const encodedSku = encodeURIComponent(sku);
  const url = `https://api.magalu.com/seller/v1/portfolios/skus/${encodedSku}`;

  try {
    const response = await fetch(url, {
      method: 'GET',
      headers: {
        'Accept': 'application/json',
        'Authorization': `Bearer ${token}`
      }
    });

    if (!response.ok) {
      if (response.status === 401) {
        throw new Error('Não autorizado (401). Verifique se seu Token está correto.');
      }
      if (response.status === 404) {
        throw new Error('Produto não encontrado (404). Verifique o SKU.');
      }
      throw new Error(`Erro na API: ${response.status} ${response.statusText}`);
    }

    const data = await response.json();
    return data as Product;
  } catch (error: any) {
    if (error.message === 'Failed to fetch') {
      throw new Error('Falha na conexão. Isso pode ser um bloqueio de CORS.');
    }
    throw error;
  }
};

/**
 * Fetches the price of a single product (SKU).
 */
export const fetchProductPrice = async (sku: string, token: string): Promise<PriceResponse> => {
  if (!sku) throw new Error('O SKU é obrigatório.');
  if (!token) throw new Error('O token de acesso é obrigatório.');

  const encodedSku = encodeURIComponent(sku);
  // Using query params for single sku if following the list pattern, OR path param if available.
  // The user prompt showed https://api.magalu.com/seller/v1/portfolios/prices/:sku
  const url = `https://api.magalu.com/seller/v1/portfolios/prices/${encodedSku}`;

  try {
    const response = await fetch(url, {
      method: 'GET',
      headers: {
        'Accept': 'application/json',
        'Authorization': `Bearer ${token}`
      }
    });

    // Price API usually returns 200 with empty list if not found, or 404.
    if (!response.ok) {
       // If 404 on price, we just return empty results rather than throwing, to allow product display
       if (response.status === 404) {
         return { results: [], meta: { page: { count: 0, limit: 0, offset: 0, max_limit: 0 }, links: { self: '' } } };
       }
       throw new Error(`Erro Preço: ${response.status}`);
    }

    const data = await response.json();
    return data as PriceResponse;
  } catch (error: any) {
    console.error("Failed to fetch price", error);
    // Return empty structure on error to not block UI
    return { results: [], meta: { page: { count: 0, limit: 0, offset: 0, max_limit: 0 }, links: { self: '' } } };
  }
};

/**
 * Fetches the stock of a single product (SKU).
 */
export const fetchProductStock = async (sku: string, token: string): Promise<StockResponse> => {
  if (!sku) throw new Error('O SKU é obrigatório.');
  if (!token) throw new Error('O token de acesso é obrigatório.');

  const encodedSku = encodeURIComponent(sku);
  const url = `https://api.magalu.com/seller/v1/portfolios/stocks/${encodedSku}`;

  try {
    const response = await fetch(url, {
      method: 'GET',
      headers: {
        'Accept': 'application/json',
        'Authorization': `Bearer ${token}`
      }
    });

    if (!response.ok) {
       // If 404 on stock, return empty results
       if (response.status === 404) {
         return { results: [], meta: { page: { count: 0, limit: 0, offset: 0, max_limit: 0 }, links: { self: '' } } };
       }
       throw new Error(`Erro Estoque: ${response.status}`);
    }

    const data = await response.json();
    return data as StockResponse;
  } catch (error: any) {
    console.error("Failed to fetch stock", error);
    // Return empty structure on error to not block UI
    return { results: [], meta: { page: { count: 0, limit: 0, offset: 0, max_limit: 0 }, links: { self: '' } } };
  }
};

import React, { useState, useEffect } from 'react';
import { InputSection } from './components/InputSection';
import { OrderVisualizer } from './components/OrderVisualizer';
import { RawJsonViewer } from './components/RawJsonViewer';
import { OrdersList } from './components/OrdersList';
import { ProductsList } from './components/ProductsList';
import { ProductVisualizer } from './components/ProductVisualizer';
import { fetchOrder, fetchOrdersList, fetchPortfolio, fetchProduct, fetchProductPrice, fetchProductStock } from './services/magaluService';
import { Order, OrdersListResponse, PortfolioResponse, Product, PriceDetail, StockDetail } from './types';
import { ShoppingBag, AlertCircle, Eye, EyeOff, List, Search, Key, Package, RefreshCw, Box } from 'lucide-react';

type Tab = 'search' | 'list' | 'products';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>('search');

  // Global State
  const [token, setToken] = useState('');

  // Search Mode State
  const [order, setOrder] = useState<Order | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // List Mode State
  const [listData, setListData] = useState<OrdersListResponse | null>(null);
  const [listLoading, setListLoading] = useState(false);
  const [listError, setListError] = useState<string | null>(null);
  const [viewingOrderFromList, setViewingOrderFromList] = useState<Order | null>(null);

  // Products Mode State
  const [productsData, setProductsData] = useState<PortfolioResponse | null>(null);
  const [productsLoading, setProductsLoading] = useState(false);
  const [productsError, setProductsError] = useState<string | null>(null);
  const [productsLimit, setProductsLimit] = useState(20);

  // Product Search State
  const [productSearchSku, setProductSearchSku] = useState('');
  const [singleProduct, setSingleProduct] = useState<Product | null>(null);
  const [singleProductPrice, setSingleProductPrice] = useState<PriceDetail | undefined>(undefined);
  const [singleProductStock, setSingleProductStock] = useState<StockDetail | undefined>(undefined);
  const [singleProductLoading, setSingleProductLoading] = useState(false);
  const [singleProductError, setSingleProductError] = useState<string | null>(null);

  const [showRawJson, setShowRawJson] = useState(false);

  // Sync token from localStorage on mount
  useEffect(() => {
    const savedToken = localStorage.getItem('magalu_api_token');
    if (savedToken) setToken(savedToken);
  }, []);

  const handleSearch = async (orderCode: string) => {
    if (!token) {
      setError('Por favor, insira o Token Magalu no topo da página.');
      return;
    }
    setLoading(true);
    setError(null);
    setOrder(null);
    setShowRawJson(false);

    try {
      const data = await fetchOrder(orderCode, token);
      setOrder(data);
    } catch (err: any) {
      setError(err.message || 'Ocorreu um erro desconhecido ao buscar o pedido.');
    } finally {
      setLoading(false);
    }
  };

  const handleListFetch = async (offset: number = 0) => {
    if (!token) {
      setListError('Por favor, insira o Token Magalu no topo da página.');
      return;
    }

    setListLoading(true);
    setListError(null);
    setViewingOrderFromList(null); // Reset detail view when pagination changes

    try {
      const data = await fetchOrdersList(token, offset);
      setListData(data);
    } catch (err: any) {
      setListError(err.message || 'Erro ao buscar lista de pedidos.');
    } finally {
      setListLoading(false);
    }
  };

  const handleProductsFetch = async (offset: number = 0, newLimit?: number) => {
    if (!token) {
      setProductsError('Por favor, insira o Token Magalu no topo da página.');
      return;
    }

    const limitToUse = newLimit || productsLimit;
    if (newLimit && newLimit !== productsLimit) {
      setProductsLimit(newLimit);
    }

    setProductsLoading(true);
    setProductsError(null);
    setSingleProduct(null); // Clear single search when listing

    try {
      const data = await fetchPortfolio(token, offset, limitToUse);
      setProductsData(data);
    } catch (err: any) {
      setProductsError(err.message || 'Erro ao buscar lista de produtos.');
    } finally {
      setProductsLoading(false);
    }
  };

  const handleProductSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!token) {
      setProductsError('Por favor, insira o Token Magalu no topo da página.');
      return;
    }
    if (!productSearchSku.trim()) return;

    setSingleProductLoading(true);
    setProductsError(null);
    setSingleProductError(null);
    setSingleProduct(null);
    setSingleProductPrice(undefined);
    setSingleProductStock(undefined);
    setShowRawJson(false);

    try {
      // Fetch Product, Price and Stock in parallel.
      const sku = productSearchSku.trim();
      const productPromise = fetchProduct(sku, token);
      const pricePromise = fetchProductPrice(sku, token);
      const stockPromise = fetchProductStock(sku, token);

      const [product, priceResponse, stockResponse] = await Promise.all([productPromise, pricePromise, stockPromise]);

      setSingleProduct(product);

      // Handle Price
      if (priceResponse && priceResponse.results && priceResponse.results.length > 0) {
        setSingleProductPrice(priceResponse.results[0]);
      } else {
        setSingleProductPrice(undefined);
      }

      // Handle Stock
      if (stockResponse && stockResponse.results && stockResponse.results.length > 0) {
        // Try to find one with type 'AVAILABLE', otherwise take first
        const availableStock = stockResponse.results.find(s => s.type === 'AVAILABLE') || stockResponse.results[0];
        setSingleProductStock(availableStock);
      } else {
        setSingleProductStock(undefined);
      }

    } catch (err: any) {
      setSingleProductError(err.message || 'Erro ao buscar produto.');
    } finally {
      setSingleProductLoading(false);
    }
  };

  const handleProductLimitChange = (newLimit: number) => {
    handleProductsFetch(0, newLimit);
  };

  const handleTabChange = (tab: Tab) => {
    setActiveTab(tab);
    setError(null);
    setListError(null);
    setProductsError(null);
    setSingleProductError(null);
    setShowRawJson(false);
  };

  return (
    <div className="min-h-screen bg-gray-50 pb-12">
      {/* Navbar / Header */}
      <header className="bg-white shadow-sm border-b border-gray-200 sticky top-0 z-20">
        <div className="max-w-6xl mx-auto px-4 py-4 space-y-4">

          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
            <div className="flex items-center gap-3">
              <div className="bg-blue-600 p-2 rounded-lg text-white shadow-blue-200">
                <ShoppingBag size={24} />
              </div>
              <div>
                 <h1 className="text-xl font-bold text-gray-900 tracking-tight">Magalu Order Viewer</h1>
              </div>
            </div>

            {/* Navigation Tabs */}
            <div className="flex p-1 bg-gray-100 rounded-lg overflow-x-auto">
              <button
                onClick={() => handleTabChange('search')}
                className={`px-4 py-2 text-sm font-medium rounded-md flex items-center gap-2 transition-all whitespace-nowrap ${
                  activeTab === 'search' 
                    ? 'bg-white text-blue-600 shadow-sm' 
                    : 'text-gray-500 hover:text-gray-700'
                }`}
              >
                <Search size={16} /> Buscar Pedido
              </button>
              <button
                onClick={() => handleTabChange('list')}
                className={`px-4 py-2 text-sm font-medium rounded-md flex items-center gap-2 transition-all whitespace-nowrap ${
                  activeTab === 'list' 
                    ? 'bg-white text-blue-600 shadow-sm' 
                    : 'text-gray-500 hover:text-gray-700'
                }`}
              >
                <List size={16} /> Listar Pedidos
              </button>
              <button
                onClick={() => handleTabChange('products')}
                className={`px-4 py-2 text-sm font-medium rounded-md flex items-center gap-2 transition-all whitespace-nowrap ${
                  activeTab === 'products' 
                    ? 'bg-white text-blue-600 shadow-sm' 
                    : 'text-gray-500 hover:text-gray-700'
                }`}
              >
                <Package size={16} /> Produtos
              </button>
            </div>
          </div>

          {/* Global Token Input */}
          <div className="relative">
             <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
               <Key size={16} className="text-gray-400" />
             </div>
             <input 
               type="password" 
               value={token}
               onChange={(e) => {
                 setToken(e.target.value);
                 localStorage.setItem('magalu_api_token', e.target.value);
               }}
               placeholder="Insira seu Token Magalu (Bearer) aqui para habilitar as consultas..."
               className="w-full pl-10 pr-4 py-2 bg-gray-50 border border-gray-200 rounded-lg text-sm focus:bg-white focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all shadow-sm"
             />
          </div>

        </div>
      </header>

      {/* Main Content */}
      <main className="max-w-6xl mx-auto px-4 py-8">

        {/* --- TAB: SEARCH ORDERS --- */}
        {activeTab === 'search' && (
          <div className="animate-fade-in">
            <InputSection onSearch={handleSearch} loading={loading} />

            {error && (
              <div className="mb-8 bg-red-50 border-l-4 border-red-500 p-4 rounded-r-lg flex items-start gap-3">
                <AlertCircle className="text-red-500 mt-0.5" size={20} />
                <div>
                  <h3 className="text-red-800 font-medium">Erro na consulta</h3>
                  <p className="text-red-700 text-sm mt-1">{error}</p>
                </div>
              </div>
            )}

            {order && (
              <div className="animate-fade-in-up">
                <div className="flex justify-end mb-4">
                   <button 
                    onClick={() => setShowRawJson(!showRawJson)}
                    className="text-sm text-gray-500 hover:text-blue-600 flex items-center gap-2 px-3 py-1 rounded-full border border-transparent hover:border-gray-200 transition-all"
                   >
                     {showRawJson ? <EyeOff size={14} /> : <Eye size={14} />}
                     {showRawJson ? 'Ocultar JSON Bruto' : 'Ver JSON Bruto'}
                   </button>
                </div>

                <OrderVisualizer order={order} />

                {showRawJson && <RawJsonViewer data={order} />}
              </div>
            )}

            {!order && !loading && !error && (
                <div className="text-center py-20 opacity-50">
                    <div className="inline-block p-6 bg-gray-100 rounded-full mb-4">
                        <ShoppingBag size={48} className="text-gray-400" />
                    </div>
                    <h3 className="text-lg font-medium text-gray-600">Nenhum pedido carregado</h3>
                    <p className="text-gray-400">Insira o Código do Pedido abaixo para visualizar.</p>
                </div>
            )}
          </div>
        )}

        {/* --- TAB: LIST ORDERS --- */}
        {activeTab === 'list' && (
          <div className="animate-fade-in">

            {/* Controls */}
            <div className="bg-white rounded-xl shadow-md p-4 mb-6 border border-gray-100 flex justify-end">
               <button
                  onClick={() => handleListFetch(0)}
                  disabled={listLoading || !token}
                  className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:bg-blue-300 disabled:cursor-not-allowed font-medium transition-colors flex items-center gap-2"
               >
                 {listLoading ? <RefreshCw size={18} className="animate-spin" /> : <List size={18} />}
                 {listLoading ? 'Carregando...' : 'Atualizar Lista'}
               </button>
            </div>

            {listError && (
              <div className="mb-6 bg-red-50 border-l-4 border-red-500 p-4 rounded-r-lg flex items-start gap-3">
                <AlertCircle className="text-red-500 mt-0.5" size={20} />
                <div>
                  <h3 className="text-red-800 font-medium">Erro ao listar</h3>
                  <p className="text-red-700 text-sm mt-1">{listError}</p>
                </div>
              </div>
            )}

            {viewingOrderFromList ? (
               // Detail View from List
               <div className="animate-fade-in-up">
                  <OrderVisualizer 
                    order={viewingOrderFromList} 
                    onBack={() => setViewingOrderFromList(null)} 
                  />
                  <div className="mt-8">
                    <RawJsonViewer data={viewingOrderFromList} />
                  </div>
               </div>
            ) : (
               // List View
               <>
                 {listData ? (
                   <OrdersList 
                      orders={listData.results} 
                      meta={listData.meta} 
                      onPageChange={handleListFetch}
                      onViewOrder={setViewingOrderFromList}
                      loading={listLoading}
                   />
                 ) : (
                   !listLoading && !listError && (
                    <div className="text-center py-20 opacity-50">
                        <div className="inline-block p-6 bg-gray-100 rounded-full mb-4">
                            <List size={48} className="text-gray-400" />
                        </div>
                        <h3 className="text-lg font-medium text-gray-600">Lista vazia</h3>
                        <p className="text-gray-400">
                          {!token ? "Insira seu Token no topo da página e clique em Atualizar." : "Clique em Atualizar Lista para carregar."}
                        </p>
                    </div>
                   )
                 )}
               </>
            )}
          </div>
        )}

        {/* --- TAB: PRODUCTS (PORTFOLIO) --- */}
        {activeTab === 'products' && (
          <div className="animate-fade-in">

             {/* Product Search & List Controls */}
             <div className="bg-white rounded-xl shadow-md p-6 mb-6 border border-gray-100">
               <div className="flex flex-col md:flex-row items-end gap-4 justify-between">

