                        className="flex-1 px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                      />
                      <button 
                        type="submit"
                        disabled={singleProductLoading || !token}
                        className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:bg-blue-300 font-medium flex items-center gap-2"
                      >
                         {singleProductLoading ? <RefreshCw className="animate-spin" size={18}/> : <Search size={18} />}
                         Buscar SKU
                      </button>
                    </div>
                  </form>

                  <div className="hidden md:block w-px h-12 bg-gray-200 mx-2"></div>

                  {/* List Button */}
                  <div className="w-full md:w-auto">
                     <label className="block text-sm font-medium text-gray-700 mb-1 invisible">Ação</label>
                     <button
                        onClick={() => handleProductsFetch(0)}
                        disabled={productsLoading || !token}
                        className="w-full px-6 py-2 bg-white text-gray-700 border border-gray-300 rounded-lg hover:bg-gray-50 disabled:opacity-50 font-medium flex items-center justify-center gap-2"
                     >
                       {productsLoading ? <RefreshCw size={18} className="animate-spin" /> : <List size={18} />}
                       Listar Todos
                     </button>
                  </div>
               </div>
             </div>

            {/* Error Messages */}
            {(productsError || singleProductError) && (
              <div className="mb-6 bg-red-50 border-l-4 border-red-500 p-4 rounded-r-lg flex items-start gap-3">
                <AlertCircle className="text-red-500 mt-0.5" size={20} />
                <div>
                  <h3 className="text-red-800 font-medium">Erro</h3>
                  <p className="text-red-700 text-sm mt-1">{productsError || singleProductError}</p>
                </div>
              </div>
            )}

            {/* View Logic: Single Product OR List */}
            {singleProduct ? (
              <div className="animate-fade-in-up">
                 <ProductVisualizer 
                    product={singleProduct} 
                    price={singleProductPrice}
                    stock={singleProductStock}
                    onBack={() => setSingleProduct(null)} 
                 />
                 <div className="mt-8">
                   <div className="flex justify-end mb-2">
                     <button 
                       onClick={() => setShowRawJson(!showRawJson)}
                       className="text-xs text-gray-500 hover:text-blue-600 underline flex items-center gap-1"
                     >
                       {showRawJson ? <EyeOff size={12} /> : <Eye size={12} />}
                       {showRawJson ? 'Ocultar JSON' : 'Ver JSON Bruto'}
                     </button>
                   </div>
                   {showRawJson && (
                     <div className="space-y-4">
                        <div>
                          <p className="text-xs font-bold text-gray-500 mb-1">Produto</p>
                          <RawJsonViewer data={singleProduct} />
                        </div>
                        {singleProductPrice && (
                          <div>
                            <p className="text-xs font-bold text-gray-500 mb-1">Preço</p>
                            <RawJsonViewer data={singleProductPrice} />
                          </div>
                        )}
                        {singleProductStock && (
                          <div>
                            <p className="text-xs font-bold text-gray-500 mb-1">Estoque</p>
                            <RawJsonViewer data={singleProductStock} />
                          </div>
                        )}
                     </div>
                   )}
                 </div>
              </div>
            ) : productsData ? (
              <>
                <ProductsList 
                  products={productsData.results}
                  meta={productsData.meta}
                  onPageChange={(offset) => handleProductsFetch(offset)}
                  loading={productsLoading}
                  limit={productsLimit}
                  onLimitChange={handleProductLimitChange}
                />
                <div className="mt-8">
                  <div className="flex justify-end mb-2">
                    <button 
                      onClick={() => setShowRawJson(!showRawJson)}
                      className="text-xs text-gray-500 hover:text-blue-600 underline"
                    >
                      {showRawJson ? 'Ocultar JSON' : 'Ver JSON Bruto'}
                    </button>
                  </div>
                  {showRawJson && <RawJsonViewer data={productsData} />}
                </div>
              </>
            ) : (
              !productsLoading && !productsError && !singleProductLoading && !singleProductError && (
                <div className="text-center py-20 opacity-50">
                    <div className="inline-block p-6 bg-gray-100 rounded-full mb-4">
                        <Package size={48} className="text-gray-400" />
                    </div>
                    <h3 className="text-lg font-medium text-gray-600">Área de Produtos</h3>
                    <p className="text-gray-400">
                      Pesquise um SKU específico acima ou clique em "Listar Todos".
                    </p>
                </div>
              )
            )}
          </div>
        )}

      </main>
    </div>
  );
};

export default App;

import React from 'react';
import { Product, PriceDetail, StockDetail } from '../types';
import { getStatusConfig, formatDate, formatValue } from '../utils';
import { 
  Box, Ruler, Tag, Calendar, Globe, ExternalLink, Barcode, Layers, ImageOff, TrendingDown, Clock, PackageCheck
} from 'lucide-react';

interface ProductVisualizerProps {
  product: Product;
  price?: PriceDetail;
  stock?: StockDetail;
  onBack?: () => void;
}

export const ProductVisualizer: React.FC<ProductVisualizerProps> = ({ product, price, stock, onBack }) => {
  const status = getStatusConfig(product.status);
  const mainImage = product.images?.[0]?.reference;
  const marketplaceUrl = product.url_marketplace?.find(u => u.channel === 'magazineluiza')?.url;

  // Find EAN/GTIN if available
  const ean = product.identifiers?.find(id => id.type === 'EAN' || id.type === 'GTIN')?.value;

  // Extract dimensions (usually the first element in the array for the product itself)
  const dims = product.dimensions?.[0];

  return (
    <div className="space-y-6 animate-fade-in font-sans">

      {onBack && (
        <button 
          onClick={onBack}
          className="text-sm text-blue-600 hover:text-blue-800 hover:underline mb-2 flex items-center gap-1"
        >
          &larr; Voltar para a lista
        </button>
      )}

      {/* Header Card */}
      <div className="bg-white rounded-xl shadow-lg border border-gray-200 overflow-hidden relative">
        <div className="absolute top-0 left-0 w-2 h-full bg-gradient-to-b from-blue-500 to-blue-700"></div>

        <div className="p-6 md:p-8 flex flex-col md:flex-row gap-6 md:gap-8">
          {/* Product Image */}
          <div className="flex-shrink-0">
             <div className="w-32 h-32 md:w-40 md:h-40 bg-white border border-gray-200 rounded-lg flex items-center justify-center overflow-hidden shadow-inner p-2">
                {mainImage ? (
                  <img src={mainImage} alt={product.title} className="w-full h-full object-contain" />
                ) : (
                  <ImageOff size={40} className="text-gray-300" />
                )}
             </div>
          </div>

          {/* Main Info */}
          <div className="flex-1 space-y-3">
             <div className="flex flex-wrap items-start justify-between gap-4">
                <div className="flex-1 min-w-[200px]">
                   <span className="text-xs font-bold text-gray-400 uppercase tracking-wider bg-gray-100 px-2 py-1 rounded border border-gray-200">
                     {product.brand}
                   </span>
                   <h2 className="text-2xl font-extrabold text-gray-900 leading-tight mt-2">
                      {product.title}
                   </h2>
                   <div className="flex items-center gap-3 mt-1 text-gray-500 font-mono text-sm">
                      <span className="flex items-center gap-1"><Tag size={14}/> SKU: {product.sku}</span>
                      {ean && (
                        <span className="flex items-center gap-1 border-l border-gray-300 pl-3">
                           <Barcode size={14}/> EAN: {ean}
                        </span>
                      )}
                   </div>
                </div>

                <div className="flex flex-col items-end gap-2">
                  <div className={`px-4 py-2 rounded-lg font-bold text-sm flex items-center gap-2 border ${status.style}`}>
                     {status.icon}
                     <span>{status.label}</span>
                  </div>

                  {/* Pricing Section - Prominent */}
                  {price && (
                    <div className="bg-blue-50 rounded-xl p-3 border border-blue-100 text-right min-w-[180px]">
                       <div className="text-xs text-gray-400 line-through">
                         De: {formatValue(price.list_price, price.normalizer)}
                       </div>
                       <div className="text-2xl font-extrabold text-blue-700 leading-none mt-0.5">
                         {formatValue(price.price, price.normalizer)}
                       </div>
                       <div className="text-[10px] text-blue-400 mt-1 flex items-center justify-end gap-1">
                         <Clock size={10} /> Atualizado: {formatDate(price.updated_at)}
                       </div>
                    </div>
                  )}
                  {!price && (
                     <div className="text-xs text-gray-400 italic mt-1">Preço indisponível</div>
                  )}

                  {/* Stock Section */}
                  {stock && (
                    <div className={`mt-1 px-3 py-1.5 rounded-lg border flex items-center justify-between gap-3 w-full max-w-[180px] ${stock.quantity > 0 ? 'bg-green-50 border-green-100 text-green-700' : 'bg-red-50 border-red-100 text-red-700'}`}>
                       <div className="flex items-center gap-1.5 text-xs font-bold uppercase">
                          <PackageCheck size={14} />
                          <span>Estoque</span>
                       </div>
                       <span className="font-mono font-bold text-base">{stock.quantity}</span>
                    </div>
                  )}
                </div>
             </div>

             <div className="pt-2 flex flex-wrap gap-4 text-sm text-gray-500">
                <span className="flex items-center gap-1.5 bg-gray-50 px-3 py-1.5 rounded-full border border-gray-100">
                  <Calendar size={14} className="text-gray-400" /> 
                  Criado: <span className="font-medium text-gray-700">{formatDate(product.created_at)}</span>
                </span>
                <span className="flex items-center gap-1.5 bg-gray-50 px-3 py-1.5 rounded-full border border-gray-100">
                  <Layers size={14} className="text-gray-400" /> 
                  Condição: <span className="font-medium text-gray-700">{product.condition}</span>
                </span>
             </div>

             {marketplaceUrl && (
                <div className="pt-2">
                  <a 
                    href={marketplaceUrl} 
                    target="_blank" 
                    rel="noopener noreferrer"
