         {/* Dimensions Card */}
         <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6">
            <h3 className="text-sm font-bold text-gray-800 uppercase tracking-wider mb-4 flex items-center gap-2 pb-2 border-b border-gray-100">
              <Ruler size={18} className="text-blue-500" /> Dimensões e Peso
            </h3>

            {dims ? (
              <div className="grid grid-cols-2 gap-4">
                 <div className="bg-gray-50 p-3 rounded-lg border border-gray-100">
                    <span className="text-xs text-gray-400 uppercase font-bold">Altura</span>
                    <p className="font-mono text-lg font-medium text-gray-800">
                       {dims.height.value} <span className="text-sm text-gray-500">{dims.height.unit}</span>
                    </p>
                 </div>
                 <div className="bg-gray-50 p-3 rounded-lg border border-gray-100">
                    <span className="text-xs text-gray-400 uppercase font-bold">Largura</span>
                    <p className="font-mono text-lg font-medium text-gray-800">
                       {dims.width.value} <span className="text-sm text-gray-500">{dims.width.unit}</span>
                    </p>
                 </div>
                 <div className="bg-gray-50 p-3 rounded-lg border border-gray-100">
                    <span className="text-xs text-gray-400 uppercase font-bold">Comprimento</span>
                    <p className="font-mono text-lg font-medium text-gray-800">
                       {dims.length.value} <span className="text-sm text-gray-500">{dims.length.unit}</span>
                    </p>
                 </div>
                 <div className="bg-gray-50 p-3 rounded-lg border border-gray-100">
                    <span className="text-xs text-gray-400 uppercase font-bold">Peso</span>
                    <p className="font-mono text-lg font-medium text-gray-800">
                       {dims.weight.value} <span className="text-sm text-gray-500">{dims.weight.unit}</span>
                    </p>
                 </div>
              </div>
            ) : (
              <p className="text-gray-400 italic">Informações de dimensão não disponíveis.</p>
            )}
         </div>

         {/* Attributes / Identifiers */}
         <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6">
            <h3 className="text-sm font-bold text-gray-800 uppercase tracking-wider mb-4 flex items-center gap-2 pb-2 border-b border-gray-100">
              <Box size={18} className="text-blue-500" /> Ficha Técnica
            </h3>

            <div className="space-y-3 max-h-60 overflow-y-auto pr-2 custom-scrollbar">
               {product.identifiers && product.identifiers.length > 0 && (
                 <div className="mb-4">
                    <h4 className="text-xs font-bold text-gray-400 mb-2">Identificadores</h4>
                    <div className="space-y-1">
                      {product.identifiers.map((id, idx) => (
                         <div key={idx} className="flex justify-between text-sm">
                            <span className="text-gray-600 font-medium">{id.type}:</span>
                            <span className="font-mono text-gray-800">{id.value}</span>
                         </div>
                      ))}
                    </div>
                 </div>
               )}

               {product.attributes && product.attributes.length > 0 ? (
                 <div>
                    <h4 className="text-xs font-bold text-gray-400 mb-2">Atributos</h4>
                    <div className="divide-y divide-gray-100">
                      {product.attributes.map((attr, idx) => (
                         <div key={idx} className="flex justify-between py-1.5 text-sm">
                            <span className="text-gray-600">{attr.name}</span>
                            <span className="text-gray-800 font-medium text-right ml-4">{attr.value}</span>
                         </div>
                      ))}
                    </div>
                 </div>
               ) : (
                 <p className="text-gray-400 italic">Nenhum atributo adicional listado.</p>
               )}
            </div>
         </div>

      </div>

      {/* Description */}
      {product.description && (
        <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6">
          <h3 className="text-sm font-bold text-gray-800 uppercase tracking-wider mb-4 border-b border-gray-100 pb-2">
            Descrição
          </h3>
          <div className="prose prose-sm text-gray-600 max-w-none">
             {product.description}
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { InputSection } from './components/InputSection';
import { OrderVisualizer } from './components/OrderVisualizer';
import { RawJsonViewer } from './components/RawJsonViewer';
import { OrdersList } from './components/OrdersList';
import { ProductsList } from './components/ProductsList';
import { ProductVisualizer } from './components/ProductVisualizer';
import { fetchOrder, fetchOrdersList, fetchPortfolio, fetchProduct, fetchProductPrice, fetchProductStock } from './services/magaluService';
import { Order, OrdersListResponse, PortfolioResponse, Product, PriceDetail, StockDetail } from './types';
import { ShoppingBag, AlertCircle, Eye, EyeOff, List, Search, Key, Package, RefreshCw, Box } from 'lucide-react';

type Tab = 'search' | 'list' | 'products';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>('search');

  // Global State
  const [token, setToken] = useState('');

  // Search Mode State
  const [order, setOrder] = useState<Order | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // List Mode State
  const [listData, setListData] = useState<OrdersListResponse | null>(null);
  const [listLoading, setListLoading] = useState(false);
  const [listError, setListError] = useState<string | null>(null);
  const [viewingOrderFromList, setViewingOrderFromList] = useState<Order | null>(null);

  // Products Mode State
  const [productsData, setProductsData] = useState<PortfolioResponse | null>(null);
  const [productsLoading, setProductsLoading] = useState(false);
  const [productsError, setProductsError] = useState<string | null>(null);
  const [productsLimit, setProductsLimit] = useState(20);

  // Product Search State
  const [productSearchSku, setProductSearchSku] = useState('');
  const [singleProduct, setSingleProduct] = useState<Product | null>(null);
  const [singleProductPrice, setSingleProductPrice] = useState<PriceDetail | undefined>(undefined);
  const [singleProductStock, setSingleProductStock] = useState<StockDetail | undefined>(undefined);
  const [singleProductLoading, setSingleProductLoading] = useState(false);
  const [singleProductError, setSingleProductError] = useState<string | null>(null);

  const [showRawJson, setShowRawJson] = useState(false);

  // Sync token from localStorage on mount
  useEffect(() => {
    const savedToken = localStorage.getItem('magalu_api_token');
    if (savedToken) setToken(savedToken);
  }, []);

  const handleSearch = async (orderCode: string) => {
    if (!token) {
      setError('Por favor, insira o Token Magalu no topo da página.');
      return;
    }
    setLoading(true);
    setError(null);
    setOrder(null);
    setShowRawJson(false);

    try {
      const data = await fetchOrder(orderCode, token);
      setOrder(data);
    } catch (err: any) {
      setError(err.message || 'Ocorreu um erro desconhecido ao buscar o pedido.');
    } finally {
      setLoading(false);
    }
  };

  const handleListFetch = async (offset: number = 0) => {
    if (!token) {
      setListError('Por favor, insira o Token Magalu no topo da página.');
      return;
    }

    setListLoading(true);
    setListError(null);
    setViewingOrderFromList(null); // Reset detail view when pagination changes

    try {
      const data = await fetchOrdersList(token, offset);
      setListData(data);
    } catch (err: any) {
      setListError(err.message || 'Erro ao buscar lista de pedidos.');
    } finally {
      setListLoading(false);
    }
  };

  const handleProductsFetch = async (offset: number = 0, newLimit?: number) => {
    if (!token) {
      setProductsError('Por favor, insira o Token Magalu no topo da página.');
      return;
    }

    const limitToUse = newLimit || productsLimit;
    if (newLimit && newLimit !== productsLimit) {
      setProductsLimit(newLimit);
    }

    setProductsLoading(true);
    setProductsError(null);
    setSingleProduct(null); // Clear single search when listing

    try {
      const data = await fetchPortfolio(token, offset, limitToUse);
      setProductsData(data);
    } catch (err: any) {
      setProductsError(err.message || 'Erro ao buscar lista de produtos.');
    } finally {
      setProductsLoading(false);
    }
  };

  const handleProductSearch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!token) {
      setProductsError('Por favor, insira o Token Magalu no topo da página.');
      return;
    }
    if (!productSearchSku.trim()) return;

    setSingleProductLoading(true);
    setProductsError(null);
    setSingleProductError(null);
    setSingleProduct(null);
    setSingleProductPrice(undefined);
    setSingleProductStock(undefined);
    setShowRawJson(false);

    try {
      // Fetch Product, Price and Stock in parallel.
      const sku = productSearchSku.trim();
      const productPromise = fetchProduct(sku, token);
      const pricePromise = fetchProductPrice(sku, token);
      const stockPromise = fetchProductStock(sku, token);

      const [product, priceResponse, stockResponse] = await Promise.all([productPromise, pricePromise, stockPromise]);

      setSingleProduct(product);

      // Handle Price
      if (priceResponse && priceResponse.results && priceResponse.results.length > 0) {
        setSingleProductPrice(priceResponse.results[0]);
      } else {
        setSingleProductPrice(undefined);
      }

      // Handle Stock
      if (stockResponse && stockResponse.results && stockResponse.results.length > 0) {
        // Try to find one with type 'AVAILABLE', otherwise take first
        const availableStock = stockResponse.results.find(s => s.type === 'AVAILABLE') || stockResponse.results[0];
        setSingleProductStock(availableStock);
      } else {
        setSingleProductStock(undefined);
      }

    } catch (err: any) {
      setSingleProductError(err.message || 'Erro ao buscar produto.');
    } finally {
      setSingleProductLoading(false);
    }
  };

  const handleProductLimitChange = (newLimit: number) => {
    handleProductsFetch(0, newLimit);
  };

  const handleTabChange = (tab: Tab) => {
    setActiveTab(tab);
    setError(null);
    setListError(null);
    setProductsError(null);
    setSingleProductError(null);
    setShowRawJson(false);
  };

  return (
    <div className="min-h-screen bg-gray-50 pb-12">
      {/* Navbar / Header */}
      <header className="bg-white shadow-sm border-b border-gray-200 sticky top-0 z-20">
        <div className="max-w-6xl mx-auto px-4 py-4 space-y-4">

          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
            <div className="flex items-center gap-3">
              <div className="bg-blue-600 p-2 rounded-lg text-white shadow-blue-200">
                <ShoppingBag size={24} />
              </div>
              <div>
                 <h1 className="text-xl font-bold text-gray-900 tracking-tight">Magalu Order Viewer</h1>
              </div>
            </div>

            {/* Navigation Tabs */}
            <div className="flex p-1 bg-gray-100 rounded-lg overflow-x-auto">
              <button
                onClick={() => handleTabChange('search')}
                className={`px-4 py-2 text-sm font-medium rounded-md flex items-center gap-2 transition-all whitespace-nowrap ${
                  activeTab === 'search' 
                    ? 'bg-white text-blue-600 shadow-sm' 
                    : 'text-gray-500 hover:text-gray-700'
                }`}
              >
                <Search size={16} /> Buscar Pedido
              </button>
              <button
                onClick={() => handleTabChange('list')}
                className={`px-4 py-2 text-sm font-medium rounded-md flex items-center gap-2 transition-all whitespace-nowrap ${
                  activeTab === 'list' 
                    ? 'bg-white text-blue-600 shadow-sm' 
                    : 'text-gray-500 hover:text-gray-700'
                }`}
              >
                <List size={16} /> Listar Pedidos
              </button>
              <button
                onClick={() => handleTabChange('products')}
                className={`px-4 py-2 text-sm font-medium rounded-md flex items-center gap-2 transition-all whitespace-nowrap ${
                  activeTab === 'products' 
                    ? 'bg-white text-blue-600 shadow-sm' 
                    : 'text-gray-500 hover:text-gray-700'
                }`}
              >
                <Package size={16} /> Produtos
              </button>
            </div>
          </div>

          {/* Global Token Input */}
          <div className="relative">
             <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
               <Key size={16} className="text-gray-400" />
             </div>
             <input 
               type="password" 
               value={token}
               onChange={(e) => {
                 setToken(e.target.value);
                 localStorage.setItem('magalu_api_token', e.target.value);
               }}
               placeholder="Insira seu Token Magalu (Bearer) aqui para habilitar as consultas..."
               className="w-full pl-10 pr-4 py-2 bg-gray-50 border border-gray-200 rounded-lg text-sm focus:bg-white focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all shadow-sm"
             />
          </div>

        </div>
      </header>

      {/* Main Content */}
      <main className="max-w-6xl mx-auto px-4 py-8">

        {/* --- TAB: SEARCH ORDERS --- */}
        {activeTab === 'search' && (
          <div className="animate-fade-in">
            <InputSection onSearch={handleSearch} loading={loading} />

            {error && (
              <div className="mb-8 bg-red-50 border-l-4 border-red-500 p-4 rounded-r-lg flex items-start gap-3">
                <AlertCircle className="text-red-500 mt-0.5" size={20} />
                <div>
                  <h3 className="text-red-800 font-medium">Erro na consulta</h3>
                  <p className="text-red-700 text-sm mt-1">{error}</p>
                </div>
              </div>
            )}

            {order && (
              <div className="animate-fade-in-up">
                <div className="flex justify-end mb-4">
                   <button 
                    onClick={() => setShowRawJson(!showRawJson)}
                    className="text-sm text-gray-500 hover:text-blue-600 flex items-center gap-2 px-3 py-1 rounded-full border border-transparent hover:border-gray-200 transition-all"
                   >
                     {showRawJson ? <EyeOff size={14} /> : <Eye size={14} />}
                     {showRawJson ? 'Ocultar JSON Bruto' : 'Ver JSON Bruto'}
                   </button>
                </div>

                <OrderVisualizer order={order} token={token} />

                {showRawJson && <RawJsonViewer data={order} />}
              </div>
            )}

            {!order && !loading && !error && (
                <div className="text-center py-20 opacity-50">
                    <div className="inline-block p-6 bg-gray-100 rounded-full mb-4">
                        <ShoppingBag size={48} className="text-gray-400" />
                    </div>
                    <h3 className="text-lg font-medium text-gray-600">Nenhum pedido carregado</h3>
                    <p className="text-gray-400">Insira o Código do Pedido abaixo para visualizar.</p>
                </div>
            )}
          </div>
        )}

        {/* --- TAB: LIST ORDERS --- */}
        {activeTab === 'list' && (
          <div className="animate-fade-in">

            {/* Controls */}
            <div className="bg-white rounded-xl shadow-md p-4 mb-6 border border-gray-100 flex justify-end">
               <button
                  onClick={() => handleListFetch(0)}
                  disabled={listLoading || !token}
                  className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:bg-blue-300 disabled:cursor-not-allowed font-medium transition-colors flex items-center gap-2"
               >
                 {listLoading ? <RefreshCw size={18} className="animate-spin" /> : <List size={18} />}
                 {listLoading ? 'Carregando...' : 'Atualizar Lista'}
               </button>
            </div>

            {listError && (
              <div className="mb-6 bg-red-50 border-l-4 border-red-500 p-4 rounded-r-lg flex items-start gap-3">
                <AlertCircle className="text-red-500 mt-0.5" size={20} />
                <div>
                  <h3 className="text-red-800 font-medium">Erro ao listar</h3>
                  <p className="text-red-700 text-sm mt-1">{listError}</p>
                </div>
              </div>
            )}

            {viewingOrderFromList ? (
               // Detail View from List
               <div className="animate-fade-in-up">
                  <OrderVisualizer 
                    order={viewingOrderFromList} 
                    token={token}
                    onBack={() => setViewingOrderFromList(null)} 
                  />
                  <div className="mt-8">
                    <RawJsonViewer data={viewingOrderFromList} />
                  </div>
               </div>
            ) : (
               // List View
               <>
                 {listData ? (
                   <OrdersList 
                      orders={listData.results} 
                      meta={listData.meta} 
                      onPageChange={handleListFetch}
                      onViewOrder={setViewingOrderFromList}
                      loading={listLoading}
                   />
                 ) : (
                   !listLoading && !listError && (
                    <div className="text-center py-20 opacity-50">
                        <div className="inline-block p-6 bg-gray-100 rounded-full mb-4">
                            <List size={48} className="text-gray-400" />
                        </div>
                        <h3 className="text-lg font-medium text-gray-600">Lista vazia</h3>
                        <p className="text-gray-400">
                          {!token ? "Insira seu Token no topo da página e clique em Atualizar." : "Clique em Atualizar Lista para carregar."}
                        </p>
                    </div>
                   )
                 )}
               </>
            )}
          </div>
        )}

        {/* --- TAB: PRODUCTS (PORTFOLIO) --- */}
        {activeTab === 'products' && (
          <div className="animate-fade-in">

             {/* Product Search & List Controls */}
             <div className="bg-white rounded-xl shadow-md p-6 mb-6 border border-gray-100">
               <div className="flex flex-col md:flex-row items-end gap-4 justify-between">

                  {/* Search Form */}
                  <form onSubmit={handleProductSearch} className="w-full md:flex-1">
                    <label htmlFor="skuSearch" className="block text-sm font-medium text-gray-700 mb-1 flex items-center gap-2">
                       <Box size={16} /> Pesquisar SKU Individual
                    </label>
                    <div className="flex gap-2">
                      <input 
                        id="skuSearch"
                        type="text" 
                        value={productSearchSku}
                        onChange={(e) => setProductSearchSku(e.target.value)}
                        placeholder="Digite o SKU do produto..."
                        className="flex-1 px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                      />
                      <button 
                        type="submit"
                        disabled={singleProductLoading || !token}
                        className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:bg-blue-300 font-medium flex items-center gap-2"
                      >
                         {singleProductLoading ? <RefreshCw className="animate-spin" size={18}/> : <Search size={18} />}
                         Buscar SKU
                      </button>
                    </div>
                  </form>

                  <div className="hidden md:block w-px h-12 bg-gray-200 mx-2"></div>

                  {/* List Button */}
                  <div className="w-full md:w-auto">
                     <label className="block text-sm font-medium text-gray-700 mb-1 invisible">Ação</label>
                     <button
                        onClick={() => handleProductsFetch(0)}
                        disabled={productsLoading || !token}
                        className="w-full px-6 py-2 bg-white text-gray-700 border border-gray-300 rounded-lg hover:bg-gray-50 disabled:opacity-50 font-medium flex items-center justify-center gap-2"
                     >
                       {productsLoading ? <RefreshCw size={18} className="animate-spin" /> : <List size={18} />}
                       Listar Todos
                     </button>
                  </div>
               </div>
             </div>

            {/* Error Messages */}
            {(productsError || singleProductError) && (
              <div className="mb-6 bg-red-50 border-l-4 border-red-500 p-4 rounded-r-lg flex items-start gap-3">
                <AlertCircle className="text-red-500 mt-0.5" size={20} />
                <div>
                  <h3 className="text-red-800 font-medium">Erro</h3>
                  <p className="text-red-700 text-sm mt-1">{productsError || singleProductError}</p>
                </div>
              </div>
            )}

            {/* View Logic: Single Product OR List */}
            {singleProduct ? (
              <div className="animate-fade-in-up">
                 <ProductVisualizer 
                    product={singleProduct} 
                    price={singleProductPrice}
                    stock={singleProductStock}
                    onBack={() => setSingleProduct(null)} 
                 />
                 <div className="mt-8">
                   <div className="flex justify-end mb-2">
                     <button 
                       onClick={() => setShowRawJson(!showRawJson)}
                       className="text-xs text-gray-500 hover:text-blue-600 underline flex items-center gap-1"
                     >
                       {showRawJson ? <EyeOff size={12} /> : <Eye size={12} />}
                       {showRawJson ? 'Ocultar JSON' : 'Ver JSON Bruto'}
                     </button>
                   </div>
                   {showRawJson && (
                     <div className="space-y-4">
                        <div>
                          <p className="text-xs font-bold text-gray-500 mb-1">Produto</p>
                          <RawJsonViewer data={singleProduct} />
                        </div>
                        {singleProductPrice && (
                          <div>
                            <p className="text-xs font-bold text-gray-500 mb-1">Preço</p>
                            <RawJsonViewer data={singleProductPrice} />
                          </div>
                        )}
                        {singleProductStock && (
                          <div>
                            <p className="text-xs font-bold text-gray-500 mb-1">Estoque</p>
                            <RawJsonViewer data={singleProductStock} />
                          </div>
                        )}
                     </div>
                   )}
                 </div>
              </div>
            ) : productsData ? (
              <>
                <ProductsList 
                  products={productsData.results}
                  meta={productsData.meta}
                  onPageChange={(offset) => handleProductsFetch(offset)}
                  loading={productsLoading}
                  limit={productsLimit}
                  onLimitChange={handleProductLimitChange}
                />
                <div className="mt-8">
                  <div className="flex justify-end mb-2">
                    <button 
                      onClick={() => setShowRawJson(!showRawJson)}
                      className="text-xs text-gray-500 hover:text-blue-600 underline"
                    >
                      {showRawJson ? 'Ocultar JSON' : 'Ver JSON Bruto'}
                    </button>
                  </div>
                  {showRawJson && <RawJsonViewer data={productsData} />}
                </div>
              </>
            ) : (
              !productsLoading && !productsError && !singleProductLoading && !singleProductError && (
                <div className="text-center py-20 opacity-50">
                    <div className="inline-block p-6 bg-gray-100 rounded-full mb-4">
                        <Package size={48} className="text-gray-400" />
                    </div>
                    <h3 className="text-lg font-medium text-gray-600">Área de Produtos</h3>
                    <p className="text-gray-400">
                      Pesquise um SKU específico acima ou clique em "Listar Todos".
                    </p>
                </div>
              )
            )}
          </div>
        )}

      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Order, Delivery, Product, PriceDetail, StockDetail } from '../types';
import { 
  User, MapPin, CreditCard, Calendar, ShoppingBag, 
  Truck, Package, CheckCircle, Clock, X, Loader
} from 'lucide-react';
import { formatValue, formatDate, getStatusConfig, getCustomerInfo } from '../utils';
import { fetchProduct, fetchProductPrice, fetchProductStock } from '../services/magaluService';
import { ProductVisualizer } from './ProductVisualizer';

interface OrderVisualizerProps {
  order: Order;
  token?: string; // Token is needed to fetch product details
  onBack?: () => void;
}

export const OrderVisualizer: React.FC<OrderVisualizerProps> = ({ order, token, onBack }) => {

  const orderStatus = getStatusConfig(order.status);
  const customer = getCustomerInfo(order);

  // Modal State
  const [selectedProductSku, setSelectedProductSku] = useState<string | null>(null);
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [selectedPrice, setSelectedPrice] = useState<PriceDetail | undefined>(undefined);
  const [selectedStock, setSelectedStock] = useState<StockDetail | undefined>(undefined);
  const [isProductLoading, setIsProductLoading] = useState(false);
  const [productError, setProductError] = useState<string | null>(null);

  // Extract shipping address from the first delivery (usually same for all)
  const shippingAddress = order.deliveries?.[0]?.shipping?.recipient?.address;
  const shippingProvider = order.deliveries?.[0]?.shipping?.provider;
  const shippingDeadline = order.deliveries?.[0]?.shipping?.deadline;

  // Handle clicking on an item to view details
  const handleViewProduct = async (sku: string) => {
    if (!token) {
      alert("Token não disponível para buscar detalhes do produto.");
      return;
    }

    setSelectedProductSku(sku);
    setIsProductLoading(true);
    setProductError(null);
    setSelectedProduct(null);
    setSelectedPrice(undefined);
    setSelectedStock(undefined);

    try {
      // Fetch data in parallel
      const [product, priceResponse, stockResponse] = await Promise.all([
        fetchProduct(sku, token),
        fetchProductPrice(sku, token),
        fetchProductStock(sku, token)
      ]);

      setSelectedProduct(product);

      if (priceResponse?.results?.length > 0) {
        setSelectedPrice(priceResponse.results[0]);
      }

      if (stockResponse?.results?.length > 0) {
        const availableStock = stockResponse.results.find(s => s.type === 'AVAILABLE') || stockResponse.results[0];
        setSelectedStock(availableStock);
      }

    } catch (err: any) {
      setProductError(err.message || "Erro ao carregar detalhes do produto.");
    } finally {
      setIsProductLoading(false);
    }
  };

  const closeModal = () => {
    setSelectedProductSku(null);
    setSelectedProduct(null);
  };

  // Helper to map util colors to vibrant solid styles
  const getVibrantStatusStyle = (color: string) => {
    const styles: Record<string, string> = {
      red: 'bg-red-600 text-white border-red-700 shadow-md shadow-red-200',
      emerald: 'bg-emerald-600 text-white border-emerald-700 shadow-md shadow-emerald-200',
      green: 'bg-green-600 text-white border-green-700 shadow-md shadow-green-200',
      blue: 'bg-blue-600 text-white border-blue-700 shadow-md shadow-blue-200',
      amber: 'bg-amber-500 text-white border-amber-600 shadow-md shadow-amber-200',
      sky: 'bg-sky-500 text-white border-sky-600 shadow-md shadow-sky-200',
      gray: 'bg-gray-500 text-white border-gray-600 shadow-md shadow-gray-200',
    };
    return styles[color] || styles.gray;
  };

  // Helper for delivery header backgrounds (lighter)
  const getDeliveryHeaderStyle = (color: string) => {
    const styles: Record<string, string> = {
      red: 'bg-red-50 border-red-200',
      emerald: 'bg-emerald-50 border-emerald-200',
      green: 'bg-green-50 border-green-200',
      blue: 'bg-blue-50 border-blue-200',
      amber: 'bg-amber-50 border-amber-200',
      sky: 'bg-sky-50 border-sky-200',
      gray: 'bg-gray-50 border-gray-200',
    };
    return styles[color] || styles.gray;
  };

  const getDeliveryTextStyle = (color: string) => {
    const styles: Record<string, string> = {
      red: 'text-red-700',
      emerald: 'text-emerald-700',
      green: 'text-green-700',
      blue: 'text-blue-700',
      amber: 'text-amber-800',
      sky: 'text-sky-700',
      gray: 'text-gray-700',
    };
    return styles[color] || styles.gray;
  };

  const vibrantStyle = getVibrantStatusStyle(orderStatus.color);

  return (
    <div className="space-y-6 animate-fade-in font-sans relative">

      {onBack && (
        <button 
          onClick={onBack}
          className="text-sm text-blue-600 hover:text-blue-800 hover:underline mb-2 flex items-center gap-1"
        >
          &larr; Voltar para a lista
        </button>
      )}

      {/* 1. Header Card - Redesigned for Prominence */}
      <div className="bg-white rounded-xl shadow-lg border border-gray-200 overflow-hidden relative">
        <div className="absolute top-0 left-0 w-2 h-full bg-gradient-to-b from-blue-500 to-blue-700"></div>

        <div className="p-6 md:p-8 flex flex-col md:flex-row md:items-center justify-between gap-6 pl-8">
          <div className="space-y-2">
             <div className="flex items-center gap-3">
               <span className="bg-gray-100 text-gray-600 text-xs font-bold px-2 py-1 rounded border border-gray-200 uppercase tracking-wider">
                 {order.channel?.extras?.alias || 'Canal Magalu'}
               </span>
               <span className="text-sm text-gray-400 font-mono">ID: {order.id}</span>
             </div>
             <h2 className="text-3xl font-extrabold text-gray-900 tracking-tight flex items-baseline gap-2">
                Pedido #{order.code}
             </h2>
             <div className="flex flex-wrap items-center gap-4 text-sm text-gray-500 pt-1">
                <span className="flex items-center gap-1.5">
                  <Calendar size={14} className="text-gray-400" /> 
                  Criado em: <span className="font-medium text-gray-700">{formatDate(order.created_at)}</span>
                </span>
                {order.approved_at && (
                  <span className="flex items-center gap-1.5">
                    <CheckCircle size={14} className="text-green-500" /> 
                    Aprovado em: <span className="font-medium text-gray-700">{formatDate(order.approved_at)}</span>
                  </span>
                )}
             </div>
          </div>

          <div className="flex flex-col items-end">
             <div className={`px-6 py-3 rounded-xl font-bold text-lg flex items-center gap-3 border-2 ${vibrantStyle} transition-transform hover:scale-105`}>
                {React.cloneElement(orderStatus.icon as React.ReactElement<any>, { size: 24, strokeWidth: 2.5 })}
                <span>{orderStatus.label}</span>
             </div>
          </div>
        </div>

        <div className="bg-gray-50 border-t border-gray-200 p-6 grid grid-cols-1 md:grid-cols-3 gap-6 md:gap-8">

          {/* Customer */}
          <div className="flex gap-4 items-start">
             <div className="p-2.5 bg-white rounded-lg shadow-sm border border-gray-100 text-gray-400">
               <User size={20} />
             </div>
             <div>
                <h3 className="text-xs font-bold text-gray-400 uppercase tracking-wider mb-1">Cliente</h3>
                <p className="font-bold text-gray-800">{customer.name}</p>
                <p className="text-sm text-gray-500 mt-0.5">{customer.document_number}</p>
                {(customer.email || customer.phone_number) && (
                   <div className="text-xs text-gray-400 mt-1 space-y-0.5">
                     {customer.email && <p>{customer.email}</p>}
                     {customer.phone_number && <p>{customer.phone_number}</p>}
                   </div>
                )}
             </div>
          </div>

          {/* Shipping Info */}
          <div className="flex gap-4 items-start">
             <div className="p-2.5 bg-white rounded-lg shadow-sm border border-gray-100 text-gray-400">
               <MapPin size={20} />
             </div>
             <div>
                <h3 className="text-xs font-bold text-gray-400 uppercase tracking-wider mb-1">Endereço de Entrega</h3>
                {shippingAddress ? (
                  <>
                    <p className="text-sm font-medium text-gray-800 leading-tight">
                      {shippingAddress.street}, {shippingAddress.number}
                    </p>
                    <p className="text-xs text-gray-500 mt-1">
                      {shippingAddress.district}, {shippingAddress.city} - {shippingAddress.state}
                    </p>
                    <p className="text-xs text-gray-500 font-mono mt-0.5">CEP: {shippingAddress.zipcode}</p>
                  </>
                ) : (
                   <p className="text-sm text-gray-400 italic">Não informado</p>
                )}
             </div>
          </div>

          {/* Payment Info */}
          <div className="flex gap-4 items-start">
             <div className="p-2.5 bg-white rounded-lg shadow-sm border border-gray-100 text-gray-400">
               <CreditCard size={20} />
             </div>
             <div className="flex-1">
                <h3 className="text-xs font-bold text-gray-400 uppercase tracking-wider mb-1">Pagamento</h3>
                {order.payments?.map((pay, idx) => (
                  <div key={idx} className="mb-2 last:mb-0">
                     <div className="flex justify-between items-baseline">
                        <span className="text-sm font-bold text-gray-800">{pay.description}</span>
                        <span className="text-xs font-mono bg-gray-200 px-1 rounded">{pay.method}</span>
                     </div>
                     <p className="text-xs text-gray-500">
                        {pay.installments}x de {formatValue(pay.amount / pay.installments, pay.normalizer)}
                     </p>
                  </div>
                ))}
                <div className="mt-2 pt-2 border-t border-gray-200 flex justify-between items-end">
                   <span className="text-xs font-medium text-gray-500">Total</span>
                   <span className="text-lg font-bold text-gray-900">{formatValue(order.amounts.total, order.amounts.normalizer)}</span>
                </div>
             </div>
          </div>
        </div>
      </div>

      {/* 2. Deliveries and Items */}
      {order.deliveries.map((delivery: Delivery, idx: number) => {
        const deliveryStatus = getStatusConfig(delivery.status);
        const headerStyle = getDeliveryHeaderStyle(deliveryStatus.color);
        const textStyle = getDeliveryTextStyle(deliveryStatus.color);
